-- Tự sinh bởi scripts/build-grammar-seed.mjs — đừng sửa tay.
-- Nội dung ngữ pháp dùng chung cho mọi user; tiến độ nằm ở bảng grammar_progress.
with payload as (select $seed$[{"slug":"tu-loai-va-cau-don","stage":1,"position":1,"title":"Từ loại và câu đơn","title_en":"Parts of speech and simple sentences","summary":"Nắm tám từ loại chính và cấu trúc câu đơn cơ bản để đặt câu đúng trật tự từ.","content":"### Từ loại cơ bản\n\nTiếng Anh có tám từ loại chính: danh từ (nouns), đại từ (pronouns), động từ (verbs), tính từ (adjectives), trạng từ (adverbs), giới từ (prepositions), liên từ (conjunctions) và từ hạn định (determiners). Mỗi từ loại giữ một vai trò riêng trong câu: danh từ gọi tên sự vật, động từ diễn tả hành động hoặc trạng thái, tính từ bổ nghĩa cho danh từ.\n\n### Cấu trúc câu đơn\n\nCâu đơn chỉ có **một mệnh đề độc lập**, thường gồm chủ ngữ (S) và vị ngữ (V): **S + V (+ O / C)**. Ví dụ: *She reads books every night* (Cô ấy đọc sách mỗi tối). Chủ ngữ có thể là danh từ, đại từ hoặc cụm danh từ; vị ngữ bắt buộc phải có động từ chính.\n\n### Trật tự từ\n\nTrật tự quen thuộc là **chủ ngữ – động từ – tân ngữ – trạng từ**: *My brother bought a new bike yesterday* (Anh trai tôi mua một chiếc xe đạp mới hôm qua). Tính từ đứng trước danh từ, trạng từ bổ nghĩa cho động từ hoặc tính từ.\n\n### Lỗi thường gặp\n\n- Thiếu động từ chính: *She very happy* → *She is very happy*.\n- Đặt tính từ sau danh từ: *a car red* → *a red car*.\n- Dùng trạng từ thay tính từ sau động từ liên kết: *He looks carefully* → *He looks careful*.","examples":[{"en":"My sister teaches English at a small school near our house.","vi":"Chị gái tôi dạy tiếng Anh tại một ngôi trường nhỏ gần nhà."},{"en":"The children played football in the park all afternoon.","vi":"Bọn trẻ chơi bóng đá trong công viên suốt cả buổi chiều."},{"en":"He speaks English very well.","vi":"Anh ấy nói tiếng Anh rất tốt."}],"exercises":[{"prompt":"___ is my favorite subject at school.","options":["Mathematics","Run","Quickly","Beautiful"],"answer":0,"explanation":"Vị trí chủ ngữ cần một danh từ nên Mathematics là đáp án đúng; run là động từ, quickly là trạng từ, beautiful là tính từ."},{"prompt":"She speaks English very ___.","options":["good","well","better","best"],"answer":1,"explanation":"Cần trạng từ bổ nghĩa cho động từ speaks nên dùng well; good là tính từ, còn better và best là dạng so sánh không phù hợp ở đây."},{"prompt":"She bought a beautiful ___ for her mother.","options":["run","quickly","dress","beautifully"],"answer":2,"explanation":"Sau tính từ beautiful phải là danh từ dress; run là động từ, quickly và beautifully là trạng từ."}],"is_new":false},{"slug":"danh-tu","stage":1,"position":2,"title":"Danh từ","title_en":"Nouns: countable, uncountable, plural","summary":"Phân biệt danh từ đếm được và không đếm được, nắm quy tắc tạo số nhiều và các dạng bất quy tắc.","content":"### Danh từ đếm được và không đếm được\n\nDanh từ đếm được (countable) có thể đứng sau số đếm và có dạng số nhiều: *one book, two books*. Danh từ không đếm được (uncountable) không có dạng số nhiều và không dùng với a/an: *water, rice, information, advice, furniture, news*.\n\n### Hình thành số nhiều\n\n- Thêm **-s** vào hầu hết danh từ: *book → books*.\n- Thêm **-es** sau -s, -sh, -ch, -x, -z: *box → boxes*.\n- Đổi **-y** thành **-ies** khi trước y là phụ âm: *city → cities*.\n- Đổi **-f/-fe** thành **-ves**: *knife → knives*.\n\n### Số nhiều bất quy tắc\n\nMột số danh từ có dạng riêng: *man → men, woman → women, child → children, tooth → teeth, foot → feet, mouse → mice*. Một số danh từ giữ nguyên ở cả hai số: *sheep, fish, deer*.\n\n### Lỗi thường gặp\n\n- Thêm -s vào danh từ không đếm được: *informations* → *information*.\n- Dùng động từ số nhiều với danh từ không đếm được: *The news are good* → *The news is good*.\n- Viết *childrens* thay vì *children*.","examples":[{"en":"There are three knives and two boxes on the table.","vi":"Có ba con dao và hai cái hộp trên bàn."},{"en":"The children need more information about the trip.","vi":"Bọn trẻ cần thêm thông tin về chuyến đi."},{"en":"Those women are buying fresh vegetables at the market.","vi":"Những người phụ nữ đó đang mua rau tươi ở chợ."}],"exercises":[{"prompt":"There are many ___ playing in the yard.","options":["child","childs","children","childrens"],"answer":2,"explanation":"Số nhiều bất quy tắc của child là children; child là số ít, childs và childrens đều sai chính tả."},{"prompt":"I need some ___ about the course.","options":["information","informations","an information","informationes"],"answer":0,"explanation":"Information là danh từ không đếm được nên không có -s và không dùng với a/an."},{"prompt":"She cut the bread with two ___.","options":["knifes","knives","knife","knife's"],"answer":1,"explanation":"Danh từ tận cùng -fe đổi thành -ves ở số nhiều: knife → knives; knifes là dạng sai."}],"is_new":true},{"slug":"mao-tu","stage":1,"position":3,"title":"Mạo từ","title_en":"Articles: a, an, the, no article","summary":"Dùng đúng a/an/the và biết khi nào không cần mạo từ trong câu tiếng Anh.","content":"### Mạo từ bất định a/an\n\nDùng **a** trước phụ âm (xét theo âm, không theo chữ): *a book, a university, a European country*. Dùng **an** trước nguyên âm: *an apple, an hour, an honest man*. A/an chỉ dùng với danh từ đếm được số ít khi người nghe chưa biết chính xác đối tượng.\n\n### Mạo từ xác định the\n\nDùng **the** khi đối tượng đã được xác định, đã nhắc trước đó, là duy nhất hoặc được xác định bởi ngữ cảnh: *the sun, the teacher in my class, the book I bought*. The dùng được với cả danh từ số ít và số nhiều.\n\n### Không dùng mạo từ\n\nKhông dùng mạo từ trước danh từ không đếm được hoặc danh từ số nhiều khi nói chung: *I like music* (Tôi thích âm nhạc), *Cats are cute* (Mèo rất đáng yêu). Cũng không dùng trước tên riêng, bữa ăn, ngôn ngữ, môn học và cụm cố định như *go to school, at home, by bus*.\n\n### Lỗi thường gặp\n\n- Dùng a/an với danh từ không đếm được: *a furniture* → *furniture* hoặc *a piece of furniture*.\n- Bỏ the trước vật duy nhất: *Sun rises* → *The sun rises*.\n- Chọn mạo từ theo chữ cái thay vì theo âm: *an university* → *a university*.","examples":[{"en":"She is an engineer at a large company.","vi":"Cô ấy là kỹ sư tại một công ty lớn."},{"en":"The sun rose early this morning.","vi":"Mặt trời mọc sớm vào sáng nay."},{"en":"We usually have breakfast at home.","vi":"Chúng tôi thường ăn sáng ở nhà."}],"exercises":[{"prompt":"My father is ___ honest man.","options":["a","an","the","no article"],"answer":1,"explanation":"Honest bắt đầu bằng nguyên âm câm /ɒ/ nên dùng an; a sai vì xét theo âm, the không dùng khi giới thiệu lần đầu."},{"prompt":"___ sun rises in the east.","options":["A","An","The","no article"],"answer":2,"explanation":"Sun là vật duy nhất nên dùng the; a/an không dùng với danh từ xác định duy nhất."},{"prompt":"We usually have ___ dinner at seven.","options":["a","an","the","no article"],"answer":3,"explanation":"Trước tên bữa ăn thường không dùng mạo từ, nên chọn no article."}],"is_new":true},{"slug":"dai-tu-va-tinh-tu-so-huu","stage":1,"position":4,"title":"Đại từ và tính từ sở hữu","title_en":"Pronouns and possessive adjectives","summary":"Phân biệt đại từ nhân xưng, tính từ sở hữu và đại từ sở hữu để tránh nhầm vị trí.","content":"### Đại từ nhân xưng\n\nĐại từ nhân xưng làm chủ ngữ gồm **I, you, he, she, it, we, they**; làm tân ngữ gồm **me, you, him, her, it, us, them**. Chủ ngữ đứng trước động từ, tân ngữ đứng sau động từ hoặc giới từ: *She called me yesterday* (Cô ấy gọi tôi hôm qua).\n\n### Tính từ sở hữu\n\nTính từ sở hữu đứng **trước danh từ**: **my, your, his, her, its, our, their**. Ví dụ: *Their house is near the park* (Nhà của họ gần công viên). Tính từ sở hữu không thay đổi theo số của danh từ: *her books*.\n\n### Đại từ sở hữu\n\nĐại từ sở hữu đứng **một mình**, thay cho danh từ đã được nhắc trước: **mine, yours, his, hers, its, ours, theirs**. Ví dụ: *This bag is mine* (Chiếc túi này là của tôi).\n\n### Lỗi thường gặp\n\n- Nhầm its và it's: *it's* = it is, còn *its* = của nó.\n- Dùng đại từ tân ngữ làm chủ ngữ: *Me and him went out* → *He and I went out*.\n- Dùng tính từ sở hữu thay đại từ sở hữu: *The book is my* → *The book is mine*.","examples":[{"en":"This umbrella is mine, and that one is yours.","vi":"Chiếc ô này là của tôi, còn chiếc kia là của bạn."},{"en":"Her parents gave her a new bike.","vi":"Bố mẹ cô ấy tặng cô ấy một chiếc xe đạp mới."},{"en":"The students finished their homework before dinner.","vi":"Học sinh làm xong bài tập về nhà trước bữa tối."}],"exercises":[{"prompt":"This notebook is ___, not yours.","options":["my","me","mine","I"],"answer":2,"explanation":"Sau động từ to be và đứng một mình cần đại từ sở hữu mine; my phải có danh từ theo sau, me và I là đại từ nhân xưng."},{"prompt":"Please give the keys to ___.","options":["I","me","my","mine"],"answer":1,"explanation":"Sau giới từ to cần đại từ tân ngữ me; I không đứng sau giới từ, my và mine là sở hữu."},{"prompt":"___ brother works in Hanoi.","options":["She","Her","Hers","She's"],"answer":1,"explanation":"Trước danh từ brother cần tính từ sở hữu her; she là đại từ chủ ngữ, hers và she's không đứng trước danh từ."}],"is_new":true},{"slug":"tinh-tu-va-trang-tu","stage":1,"position":5,"title":"Tính từ và trạng từ","title_en":"Adjectives and adverbs","summary":"Phân biệt tính từ và trạng từ, nắm vị trí và cách thành lập trạng từ thể cách.","content":"### Tính từ\n\nTính từ bổ nghĩa cho danh từ, thường đứng **trước danh từ** hoặc **sau động từ liên kết** (be, seem, look, feel, taste, become, get): *a beautiful garden* (một khu vườn đẹp), *The soup tastes good* (Món súp có vị ngon). Tính từ không đổi theo số: *two tall boys*.\n\n### Trạng từ\n\nTrạng từ bổ nghĩa cho động từ, tính từ hoặc trạng từ khác. Trạng từ thể cách thường được tạo bằng **tính từ + -ly**: *careful → carefully, quick → quickly*. Ví dụ: *She speaks English fluently* (Cô ấy nói tiếng Anh trôi chảy).\n\n### Vị trí trạng từ\n\nTrạng từ thể cách thường đứng sau động từ hoặc sau tân ngữ: *He drives carefully* (Anh ấy lái xe cẩn thận). Trạng từ chỉ tần suất (always, usually, often, never) đứng **trước động từ thường** nhưng **sau động từ to be**: *She always gets up early*, *He is never late*.\n\n### Lỗi thường gặp\n\n- Dùng tính từ thay trạng từ: *She sings beautiful* → *She sings beautifully*.\n- Dùng trạng từ sau động từ liên kết: *The food tastes badly* → *The food tastes bad*.\n- Nhầm good/well: *well* là trạng từ, *good* là tính từ.","examples":[{"en":"The little girl sang beautifully at the concert.","vi":"Cô bé hát rất hay tại buổi hòa nhạc."},{"en":"This soup tastes really good.","vi":"Món súp này có vị thực sự ngon."},{"en":"He always checks his work carefully.","vi":"Anh ấy luôn kiểm tra bài làm của mình một cách cẩn thận."}],"exercises":[{"prompt":"She sings very ___.","options":["beautiful","beautifully","beauty","beautify"],"answer":1,"explanation":"Cần trạng từ bổ nghĩa cho động từ sings nên dùng beautifully; beautiful là tính từ, beauty là danh từ, beautify là động từ."},{"prompt":"He is a ___ driver.","options":["careful","carefully","care","carefulness"],"answer":0,"explanation":"Trước danh từ driver cần tính từ careful; carefully là trạng từ, care và carefulness là danh từ."},{"prompt":"The weather feels ___ today.","options":["warm","warmly","warmth","warming"],"answer":0,"explanation":"Sau động từ liên kết feels cần tính từ warm; warmly là trạng từ, warmth là danh từ, warming không phù hợp nghĩa."}],"is_new":true},{"slug":"luong-tu","stage":1,"position":6,"title":"Lượng từ","title_en":"Quantifiers: some, any, much, many, few, little","summary":"Chọn đúng lượng từ theo loại danh từ và loại câu khẳng định, phủ định hay nghi vấn.","content":"### some và any\n\n**Some** dùng trong câu khẳng định và trong lời mời, đề nghị: *I have some money* (Tôi có một ít tiền), *Would you like some tea?*. **Any** dùng trong câu phủ định và nghi vấn: *I don't have any money*, *Do you have any questions?*.\n\n### much và many\n\n**Many** đi với danh từ đếm được số nhiều: *many books*. **Much** đi với danh từ không đếm được: *much water*. Trong câu khẳng định, người ta thường dùng *a lot of / lots of* thay cho much và many.\n\n### few, a few, little, a little\n\n- **A few + danh từ đếm được số nhiều**: một vài, đủ dùng.\n- **Few + danh từ đếm được số nhiều**: rất ít, gần như không.\n- **A little + danh từ không đếm được**: một chút, đủ dùng.\n- **Little + danh từ không đếm được**: rất ít, gần như không.\n\nVí dụ: *I have a few friends here* (Tôi có vài người bạn ở đây).\n\n### Lỗi thường gặp\n\n- Dùng much với danh từ đếm được: *much students* → *many students*.\n- Dùng any trong câu khẳng định chắc chắn: *I have any time* → *I have some time*.\n- Nhầm few và a few khiến nghĩa đảo ngược.","examples":[{"en":"We have a little sugar, but we don't have any milk.","vi":"Chúng tôi có một chút đường, nhưng không có sữa."},{"en":"How many students are there in your class?","vi":"Có bao nhiêu học sinh trong lớp của bạn?"},{"en":"Few people came to the meeting yesterday.","vi":"Rất ít người đến buổi họp hôm qua."}],"exercises":[{"prompt":"How ___ money do you need?","options":["many","much","few","a few"],"answer":1,"explanation":"Money là danh từ không đếm được nên dùng much; many, few, a few chỉ đi với danh từ đếm được số nhiều."},{"prompt":"There aren't ___ chairs in the room.","options":["some","any","much","a little"],"answer":1,"explanation":"Câu phủ định dùng any; some thường dùng trong câu khẳng định, much và a little đi với danh từ không đếm được."},{"prompt":"Hurry up! We have very ___ time left.","options":["few","a few","little","a little"],"answer":2,"explanation":"Time là danh từ không đếm được và nghĩa cần là rất ít nên dùng little; few và a few đi với danh từ đếm được, a little mang nghĩa còn đủ."}],"is_new":true},{"slug":"there-is-there-are","stage":1,"position":7,"title":"There is / There are","title_en":"There is / There are","summary":"Dùng there is/there are để nói sự tồn tại, chia đúng theo danh từ và thì của câu.","content":"### Cấu trúc cơ bản\n\n**There is + danh từ số ít hoặc không đếm được**: *There is a cat on the roof* (Có một con mèo trên mái nhà). **There are + danh từ số nhiều**: *There are two cats on the roof* (Có hai con mèo trên mái nhà). Cấu trúc này dùng để nói một vật hoặc sự việc tồn tại ở đâu đó.\n\n### Câu phủ định và nghi vấn\n\n- Phủ định: **There is not (isn't) / There are not (aren't)** + danh từ.\n- Nghi vấn: **Is there / Are there** + danh từ? Trả lời ngắn: *Yes, there is / No, there aren't*.\n- Thường dùng *some* trong câu khẳng định, *any* trong phủ định và nghi vấn: *There aren't any chairs* (Không có chiếc ghế nào).\n\n### Các thì khác\n\nThere is/are có thể chia theo thì: *There was a party last night* (Có một bữa tiệc tối qua), *There will be a meeting tomorrow* (Sẽ có một cuộc họp ngày mai), *There has been an accident* (Đã có một vụ tai nạn).\n\n### Lỗi thường gặp\n\n- Dùng have/has thay is/are: *There have a book* → *There is a book*.\n- Chia sai khi có nhiều danh từ: *There is many people* → *There are many people*.\n- Dùng there is với danh từ số nhiều: *There is three rooms* → *There are three rooms*.","examples":[{"en":"There is a small garden behind the house.","vi":"Có một khu vườn nhỏ phía sau ngôi nhà."},{"en":"There aren't any eggs in the fridge.","vi":"Không có quả trứng nào trong tủ lạnh."},{"en":"There will be a concert in the park next Sunday.","vi":"Sẽ có một buổi hòa nhạc trong công viên vào Chủ nhật tới."}],"exercises":[{"prompt":"There ___ a lamp on the desk.","options":["is","are","have","has"],"answer":0,"explanation":"A lamp là danh từ số ít nên dùng there is; are dùng cho số nhiều, have/has không đi với cấu trúc there."},{"prompt":"There ___ many people at the festival.","options":["is","are","was","has"],"answer":1,"explanation":"Many people là danh từ số nhiều nên dùng there are; is và was là số ít, has không dùng trong cấu trúc này."},{"prompt":"___ there any milk in the fridge?","options":["Is","Are","Do","Has"],"answer":0,"explanation":"Milk là danh từ không đếm được nên câu hỏi dùng Is there; Are dùng cho số nhiều, Do và Has sai cấu trúc."}],"is_new":true},{"slug":"cac-loai-cau-hoi","stage":1,"position":8,"title":"Các loại câu hỏi","title_en":"Yes/No, Wh- and tag questions","summary":"Thành lập câu hỏi Yes/No, câu hỏi Wh- và câu hỏi đuôi đúng trật tự từ và dấu.","content":"### Câu hỏi Yes/No\n\nBắt đầu bằng trợ động từ hoặc động từ to be: **Do/Does/Did, Is/Are/Was/Were, Have/Has, Can/Will...**, sau đó là chủ ngữ và động từ chính: *Do you like coffee?* (Bạn có thích cà phê không?), *Is she a doctor?* (Cô ấy là bác sĩ phải không?). Trả lời bằng Yes/No + chủ ngữ + trợ động từ.\n\n### Câu hỏi Wh-\n\nDùng **What, Where, When, Who, Why, How** ở đầu câu, sau đó là trợ động từ và chủ ngữ: *Where do you live?* (Bạn sống ở đâu?), *Why is he late?* (Vì sao anh ấy đến muộn?). Khi Who hoặc What làm chủ ngữ, không dùng trợ động từ: *Who called you?* (Ai đã gọi bạn?).\n\n### Câu hỏi đuôi\n\nCâu hỏi đuôi gồm trợ động từ + đại từ, **ngược dấu** với mệnh đề chính: *She is a teacher, isn't she?* (Cô ấy là giáo viên phải không?), *You don't smoke, do you?* (Bạn không hút thuốc phải không?). Mệnh đề khẳng định thì đuôi phủ định và ngược lại.\n\n### Lỗi thường gặp\n\n- Quên trợ động từ: *Where you live?* → *Where do you live?*.\n- Dùng danh từ trong câu hỏi đuôi: *Tom is here, isn't Tom?* → *isn't he?*.\n- Đổi dấu sai: *She isn't happy, isn't she?* → *is she?*.","examples":[{"en":"Where did you buy that beautiful dress?","vi":"Bạn đã mua chiếc váy đẹp đó ở đâu?"},{"en":"You have finished your homework, haven't you?","vi":"Bạn đã làm xong bài tập về nhà rồi phải không?"},{"en":"Does your brother work in the city center?","vi":"Anh trai bạn có làm việc ở trung tâm thành phố không?"}],"exercises":[{"prompt":"___ do you usually get up in the morning?","options":["What","Where","What time","Who"],"answer":2,"explanation":"Cần hỏi về thời gian nên dùng What time; What và Who hỏi sự vật hoặc người, Where hỏi địa điểm."},{"prompt":"She doesn't like fish, ___?","options":["does she","doesn't she","is she","isn't she"],"answer":0,"explanation":"Mệnh đề phủ định dùng trợ động từ does nên câu hỏi đuôi khẳng định là does she."},{"prompt":"___ you finished your report yet?","options":["Do","Have","Are","Did"],"answer":1,"explanation":"Trạng từ yet và quá khứ phân từ finished cho thấy thì hiện tại hoàn thành, nên dùng Have."}],"is_new":true},{"slug":"hoa-hop-chu-ngu-dong-tu","stage":1,"position":9,"title":"Hòa hợp chủ ngữ–động từ","title_en":"Subject–verb agreement","summary":"Chia động từ đúng theo chủ ngữ, kể cả các trường hợp đặc biệt và danh từ tập hợp.","content":"### Quy tắc cơ bản\n\nĐộng từ phải hòa hợp với chủ ngữ về số. Chủ ngữ số ít (he, she, it, danh từ số ít) dùng động từ thêm **-s/-es** ở hiện tại đơn: *She works here* (Cô ấy làm việc ở đây). Chủ ngữ số nhiều và I/you dùng động từ nguyên mẫu: *They work here*. Động từ to be chia **is/am/are** tương ứng.\n\n### Chủ ngữ đặc biệt\n\n- Danh từ không đếm được và *news, mathematics, physics* dùng động từ số ít: *The news is good*.\n- *Each, every, either, neither + danh từ số ít* dùng động từ số ít: *Each student has a book*.\n- *Everyone, somebody, nothing* dùng động từ số ít.\n- Hai chủ ngữ nối bằng **and** dùng động từ số nhiều: *Tom and Mary are here*.\n\n### Danh từ tập hợp\n\nFamily, team, class, government dùng động từ số ít khi xem là một đơn vị, hoặc số nhiều khi nói đến các thành viên: *The team is winning* (Đội đang thắng), *The team are arguing* (Các thành viên trong đội đang tranh cãi).\n\n### Lỗi thường gặp\n\n- Bỏ -s với chủ ngữ ngôi thứ ba số ít: *He go* → *He goes*.\n- Chia theo danh từ đứng gần: *The box of books are heavy* → *is heavy*.\n- Dùng số nhiều với every: *Every students are* → *Every student is*.","examples":[{"en":"Each of the players has a new uniform.","vi":"Mỗi cầu thủ đều có một bộ đồng phục mới."},{"en":"The news about the storm is very worrying.","vi":"Tin tức về cơn bão rất đáng lo."},{"en":"My parents go to the gym every morning.","vi":"Bố mẹ tôi đi tập thể dục mỗi sáng."}],"exercises":[{"prompt":"Each of the students ___ a dictionary.","options":["have","has","are having","were having"],"answer":1,"explanation":"Each of + danh từ số nhiều vẫn dùng động từ số ít, nên has là đáp án đúng; have và are/were là số nhiều."},{"prompt":"The news on TV ___ very surprising.","options":["are","were","is","have"],"answer":2,"explanation":"News là danh từ không đếm được nên dùng động từ số ít is; are, were, have đều là dạng số nhiều."},{"prompt":"My best friend ___ to school by bike every day.","options":["go","goes","going","gone"],"answer":1,"explanation":"Chủ ngữ my best friend là số ít nên động từ hiện tại đơn thêm -es: goes; go dùng cho số nhiều, going và gone không phải dạng chia."}],"is_new":false},{"slug":"present-simple","stage":2,"position":1,"title":"Present Simple","title_en":"Present Simple","summary":"Thì hiện tại đơn dùng cho thói quen, sự thật hiển nhiên và lịch trình cố định. Điểm cốt lõi là thêm -s/-es cho ngôi thứ ba số ít và dùng do/does trong phủ định, nghi vấn.","content":"### Công thức\n\n- Khẳng định: **S + V(s/es)**. Với I, you, we, they dùng động từ nguyên mẫu; với he, she, it thêm -s hoặc -es.\n- Phủ định: **S + do/does + not + V**. Dùng does not (doesn't) với he, she, it.\n- Nghi vấn: **Do/Does + S + V?** Trả lời ngắn: Yes, S + do/does. hoặc No, S + don't/doesn't.\n\n### Cách dùng\n\n- Thói quen, hành động lặp lại: I go to school by bus (Tôi đi học bằng xe buýt).\n- Sự thật hiển nhiên, quy luật tự nhiên: Water boils at 100 degrees (Nước sôi ở 100 độ C).\n- Lịch trình cố định: The film starts at 8 p.m (Phim bắt đầu lúc 8 giờ tối).\n- Suy nghĩ, cảm xúc, trạng thái: She likes coffee (Cô ấy thích cà phê).\n\n### Dấu hiệu nhận biết\n\n- Trạng từ tần suất: always, usually, often, sometimes, rarely, never.\n- Cụm thời gian: every day, every week, once a month, on Sundays.\n\n### Lỗi thường gặp\n\n- Bỏ quên -s/-es ở ngôi thứ ba: He go sai, phải là He goes.\n- Dùng sai trợ động từ: Does you...? sai, phải là Do you...?\n- Chia động từ sau doesn't: She doesn't likes sai, phải là She doesn't like.","examples":[{"en":"I usually get up at six o'clock.","vi":"Tôi thường thức dậy lúc sáu giờ."},{"en":"The sun rises in the east.","vi":"Mặt trời mọc ở hướng đông."},{"en":"She doesn't eat meat.","vi":"Cô ấy không ăn thịt."}],"exercises":[{"prompt":"She ___ to work every day.","options":["go","goes","going","gone"],"answer":1,"explanation":"Chủ ngữ she là ngôi thứ ba số ít nên động từ thêm -es: goes. Các lựa chọn còn lại sai vì go và gone không chia theo chủ ngữ, going thiếu trợ động từ be."},{"prompt":"___ they live in Da Nang?","options":["Do","Does","Are","Is"],"answer":0,"explanation":"Chủ ngữ they đi với trợ động từ do trong câu hỏi hiện tại đơn. Does chỉ dùng với he, she, it; are và is là dạng của be, không hợp với động từ live."},{"prompt":"My brother ___ coffee in the morning.","options":["don't drink","doesn't drink","doesn't drinks","not drink"],"answer":1,"explanation":"My brother là ngôi thứ ba số ít nên dùng doesn't và động từ giữ nguyên mẫu: doesn't drink. Không dùng don't, và sau doesn't không chia -s cho động từ."}],"is_new":false},{"slug":"present-continuous","stage":2,"position":2,"title":"Present Continuous","title_en":"Present Continuous","summary":"Thì hiện tại tiếp diễn diễn tả hành động đang xảy ra tại thời điểm nói, sự việc tạm thời hoặc xu hướng đang thay đổi. Công thức cốt lõi là am/is/are + V-ing.","content":"### Công thức\n\n- Khẳng định: **S + am/is/are + V-ing**.\n- Phủ định: **S + am/is/are + not + V-ing**.\n- Nghi vấn: **Am/Is/Are + S + V-ing?** Trả lời ngắn: Yes, S + am/is/are.\n\n### Cách dùng\n\n- Hành động đang diễn ra ngay lúc nói: She is reading a book (Cô ấy đang đọc sách).\n- Sự việc tạm thời, không kéo dài: I'm living with my aunt this month (Tháng này tôi đang ở nhà dì).\n- Thay đổi, xu hướng đang diễn ra: Prices are going up (Giá cả đang tăng).\n- Lời phàn nàn với always: He is always forgetting his keys (Anh ấy lúc nào cũng quên chìa khóa).\n\n### Dấu hiệu nhận biết\n\n- now, right now, at the moment, at present, currently.\n- Look!, Listen!, Be careful! thường đứng đầu câu.\n- this week, these days.\n\n### Lỗi thường gặp\n\n- Thiếu động từ to be: She reading sai, phải là She is reading.\n- Dùng -ing với động từ trạng thái: I am knowing sai, phải là I know.\n- Sai chính tả khi thêm -ing: run thành running, lie thành lying.","examples":[{"en":"The children are playing in the garden right now.","vi":"Bọn trẻ đang chơi trong vườn ngay lúc này."},{"en":"I'm staying at a hotel while my flat is being repaired.","vi":"Tôi đang ở khách sạn trong khi căn hộ của tôi đang được sửa."},{"en":"Prices are rising quickly this year.","vi":"Năm nay giá cả đang tăng nhanh."}],"exercises":[{"prompt":"Listen! Someone ___ at the door.","options":["knocks","knock","is knocking","knocked"],"answer":2,"explanation":"Listen! báo hiệu hành động đang diễn ra ngay lúc nói nên dùng hiện tại tiếp diễn is knocking. Knocks là hiện tại đơn, knock sai chia, knocked là quá khứ đơn."},{"prompt":"I ___ TV at the moment, so I can't talk.","options":["watch","am watching","watched","watching"],"answer":1,"explanation":"At the moment là dấu hiệu của hiện tại tiếp diễn, chủ ngữ I đi với am: am watching. Watch là thói quen, watched là quá khứ, watching thiếu to be."},{"prompt":"She ___ with her sister this month.","options":["stays","is staying","stay","stayed"],"answer":1,"explanation":"This month cho thấy một tình huống tạm thời nên dùng is staying. Stays diễn tả thói quen lâu dài, stay sai chia với she, stayed là quá khứ."}],"is_new":false},{"slug":"past-simple","stage":2,"position":3,"title":"Past Simple","title_en":"Past Simple","summary":"Thì quá khứ đơn diễn tả hành động đã kết thúc hoàn toàn trong quá khứ, thường có thời gian xác định. Cần nắm dạng V2/ed và trợ động từ did.","content":"### Công thức\n\n- Khẳng định: **S + V2/ed**. Động từ có quy tắc thêm -ed, động từ bất quy tắc phải học thuộc.\n- Phủ định: **S + did not + V** (didn't + động từ nguyên mẫu).\n- Nghi vấn: **Did + S + V?** Trả lời ngắn: Yes, S + did. hoặc No, S + didn't.\n\n### Cách dùng\n\n- Hành động đã kết thúc hoàn toàn, có thời gian xác định: I met her yesterday (Hôm qua tôi gặp cô ấy).\n- Chuỗi hành động liên tiếp: He opened the door, walked in and sat down (Anh ấy mở cửa, bước vào và ngồi xuống).\n- Thói quen trong quá khứ: We played football every Sunday (Chúng tôi chơi bóng mỗi Chủ nhật).\n\n### Dấu hiệu nhận biết\n\n- yesterday, last night, last week, two days ago.\n- in 2019, when I was a child, at that time.\n\n### Lỗi thường gặp\n\n- Dùng did với động từ đã chia: Did you went sai, phải là Did you go.\n- Dùng hiện tại hoàn hảo với mốc thời gian đã qua: I have seen him yesterday sai, phải là I saw him yesterday.\n- Nhầm dạng bất quy tắc: buy thành buyed sai, phải là bought.","examples":[{"en":"We visited Hoi An last weekend.","vi":"Chúng tôi đã đến Hội An cuối tuần trước."},{"en":"She didn't answer my call this morning.","vi":"Sáng nay cô ấy đã không nghe điện thoại của tôi."},{"en":"Did you see the match last night?","vi":"Tối qua bạn có xem trận đấu không?"}],"exercises":[{"prompt":"We ___ to Hue last summer.","options":["go","went","have gone","were going"],"answer":1,"explanation":"Last summer là thời gian đã kết thúc nên dùng quá khứ đơn went. Go là hiện tại, have gone là hiện tại hoàn hảo không đi với mốc quá khứ, were going chỉ hành động đang diễn ra."},{"prompt":"___ you finish the report yesterday?","options":["Did","Do","Have","Were"],"answer":0,"explanation":"Câu hỏi quá khứ đơn với động từ thường dùng trợ động từ did và động từ nguyên mẫu. Do là hiện tại, Have dùng cho hiện tại hoàn hảo, Were đi với V-ing."},{"prompt":"When I was a child, I ___ swimming every Sunday.","options":["go","went","have gone","am going"],"answer":1,"explanation":"When I was a child là thói quen trong quá khứ nên dùng went. Go và am going chỉ hiện tại, have gone là hiện tại hoàn hảo không hợp với thói quen đã chấm dứt."}],"is_new":false},{"slug":"past-continuous","stage":2,"position":4,"title":"Past Continuous","title_en":"Past Continuous","summary":"Thì quá khứ tiếp diễn diễn tả hành động đang diễn ra tại một thời điểm trong quá khứ hoặc làm nền cho hành động khác cắt ngang. Công thức là was/were + V-ing.","content":"### Công thức\n\n- Khẳng định: **S + was/were + V-ing**. I, he, she, it dùng was; you, we, they dùng were.\n- Phủ định: **S + was/were + not + V-ing**.\n- Nghi vấn: **Was/Were + S + V-ing?** Trả lời ngắn: Yes, S + was/were.\n\n### Cách dùng\n\n- Hành động đang diễn ra tại một thời điểm xác định trong quá khứ: At 8 p.m, I was watching TV (Lúc 8 giờ tối, tôi đang xem tivi).\n- Hành động nền bị hành động khác cắt ngang: I was sleeping when the phone rang (Tôi đang ngủ thì điện thoại reo).\n- Hai hành động song song: She was cooking while he was cleaning (Cô ấy nấu ăn trong khi anh ấy dọn dẹp).\n- Mô tả bối cảnh cho một câu chuyện: It was raining and everybody was running (Trời đang mưa và mọi người đang chạy).\n\n### Dấu hiệu nhận biết\n\n- at 7 p.m yesterday, at that time, at this time last week.\n- while, when, all day yesterday.\n\n### Lỗi thường gặp\n\n- Dùng while cho hành động ngắn cắt ngang: While the phone rang sai, phải là When the phone rang.\n- Dùng -ing với động từ trạng thái: I was knowing sai, phải là I knew.\n- Nhầm was và were: They was playing sai, phải là They were playing.","examples":[{"en":"I was cooking when he called me.","vi":"Tôi đang nấu ăn thì anh ấy gọi cho tôi."},{"en":"At nine yesterday, they were still working.","vi":"Lúc chín giờ hôm qua, họ vẫn đang làm việc."},{"en":"While I was walking home, I met an old friend.","vi":"Trong khi tôi đang đi bộ về nhà, tôi gặp một người bạn cũ."}],"exercises":[{"prompt":"At 8 p.m. yesterday, I ___ dinner.","options":["have","was having","had","am having"],"answer":1,"explanation":"At 8 p.m. yesterday là thời điểm xác định trong quá khứ nên dùng was having. Have và am having chỉ hiện tại, had diễn tả hành động đã xong chứ không phải đang diễn ra."},{"prompt":"While she ___ , the phone rang.","options":["cooks","cooked","was cooking","is cooking"],"answer":2,"explanation":"While đứng trước hành động nền kéo dài nên dùng quá khứ tiếp diễn was cooking, còn rang là hành động cắt ngang. Cooks và is cooking chỉ hiện tại, cooked là hành động đã xong."},{"prompt":"They ___ football when it started to rain.","options":["played","were playing","have played","play"],"answer":1,"explanation":"Hành động đang diễn ra thì bị started to rain cắt ngang nên dùng were playing. Played và have played nhấn mạnh kết quả đã xong, play là hiện tại đơn."}],"is_new":false},{"slug":"present-perfect","stage":2,"position":5,"title":"Present Perfect","title_en":"Present Perfect","summary":"Thì hiện tại hoàn thành nối quá khứ với hiện tại: kinh nghiệm, kết quả còn ảnh hưởng, hoặc hành động kéo dài đến bây giờ. Công thức là have/has + V3/ed.","content":"### Công thức\n\n- Khẳng định: **S + have/has + V3/ed**. I, you, we, they dùng have; he, she, it dùng has.\n- Phủ định: **S + have/has + not + V3/ed**.\n- Nghi vấn: **Have/Has + S + V3/ed?** Trả lời ngắn: Yes, S + have/has.\n\n### Cách dùng\n\n- Hành động xảy ra trong quá khứ, không nêu thời điểm, kết quả còn liên quan hiện tại: I have lost my keys (Tôi đã mất chìa khóa).\n- Kinh nghiệm sống: She has visited Japan twice (Cô ấy đã đến Nhật hai lần).\n- Hành động bắt đầu trong quá khứ và còn tiếp diễn: We have lived here since 2015 (Chúng tôi sống ở đây từ năm 2015).\n- Việc vừa xảy ra: He has just left (Anh ấy vừa mới rời đi).\n\n### Dấu hiệu nhận biết\n\n- just, already, yet, ever, never, recently, so far.\n- since + mốc thời gian, for + khoảng thời gian.\n- This is the first time...\n\n### Lỗi thường gặp\n\n- Dùng với thời gian đã kết thúc: I have met him last week sai, phải là I met him last week.\n- Nhầm since và for: since five years sai, phải là for five years.\n- Nhầm been và gone: She has gone to Paris nghĩa là cô ấy đang ở đó, còn She has been to Paris nghĩa là đã từng đến và đã về.","examples":[{"en":"I have just finished my essay.","vi":"Tôi vừa mới hoàn thành bài luận của mình."},{"en":"He has worked here for five years.","vi":"Anh ấy đã làm việc ở đây được năm năm."},{"en":"Have you ever tried Thai food?","vi":"Bạn đã từng thử món ăn Thái chưa?"}],"exercises":[{"prompt":"I ___ my homework already.","options":["finish","finished","have finished","finishing"],"answer":2,"explanation":"Already là dấu hiệu của hiện tại hoàn thành, nhấn mạnh kết quả còn liên quan hiện tại: have finished. Finish là hiện tại đơn, finished là quá khứ đơn, finishing thiếu trợ động từ."},{"prompt":"She has lived here ___ 2015.","options":["for","since","from","in"],"answer":1,"explanation":"2015 là mốc thời gian bắt đầu nên dùng since. For đi với khoảng thời gian như five years, from và in không dùng trong cấu trúc này."},{"prompt":"Have you ever ___ to Japan?","options":["be","been","went","go"],"answer":1,"explanation":"Cấu trúc have + V3 nên dùng been. Be là nguyên mẫu, went là quá khứ đơn không đứng sau have, go là hiện tại đơn."}],"is_new":false},{"slug":"past-perfect","stage":2,"position":6,"title":"Past Perfect","title_en":"Past Perfect","summary":"Thì quá khứ hoàn thành diễn tả hành động xảy ra trước một hành động hoặc mốc thời gian khác trong quá khứ. Công thức là had + V3/ed cho mọi ngôi.","content":"### Công thức\n\n- Khẳng định: **S + had + V3/ed** (dùng cho mọi ngôi).\n- Phủ định: **S + had + not + V3/ed**.\n- Nghi vấn: **Had + S + V3/ed?** Trả lời ngắn: Yes, S + had. hoặc No, S + hadn't.\n\n### Cách dùng\n\n- Hành động xảy ra trước một hành động khác trong quá khứ: The train had left when we arrived (Tàu đã rời đi khi chúng tôi đến).\n- Hành động xảy ra trước một mốc thời gian trong quá khứ: By 2020, he had written three novels (Đến năm 2020, anh ấy đã viết ba cuốn tiểu thuyết).\n- Nguyên nhân của một tình huống trong quá khứ: I was tired because I hadn't slept (Tôi mệt vì tôi đã không ngủ).\n\n### Dấu hiệu nhận biết\n\n- before, after, by the time, when (khi có hai hành động khác thời điểm).\n- already, never before, until then, by 2019.\n\n### Lỗi thường gặp\n\n- Dùng quá khứ hoàn thành khi chỉ có một hành động: I had watched a film last night sai, phải là I watched.\n- Đảo lộn trật tự: hành động xảy ra trước dùng had + V3, hành động xảy ra sau dùng quá khứ đơn.\n- Dùng had + V-ing thay vì V3: She had go sai, phải là She had gone.","examples":[{"en":"The train had left when we got to the station.","vi":"Tàu đã rời đi khi chúng tôi đến ga."},{"en":"She had never seen the sea before that trip.","vi":"Cô ấy chưa từng thấy biển trước chuyến đi đó."},{"en":"By the time I woke up, my father had gone to work.","vi":"Vào lúc tôi thức dậy, bố tôi đã đi làm rồi."}],"exercises":[{"prompt":"By the time we arrived, the film ___ .","options":["starts","started","had started","has started"],"answer":2,"explanation":"Hành động bắt đầu phim xảy ra trước việc chúng tôi đến nên dùng had started. Starts và has started chỉ hiện tại, started không thể hiện rõ thứ tự trước sau."},{"prompt":"She ___ the report before the meeting began.","options":["finished","had finished","has finished","finishes"],"answer":1,"explanation":"Before cho thấy việc hoàn thành báo cáo xảy ra trước khi cuộc họp bắt đầu, nên dùng had finished. Finished và finishes không đánh dấu quan hệ trước sau, has finished là hiện tại hoàn thành."},{"prompt":"I didn't go to the cinema because I ___ the film twice.","options":["saw","have seen","had seen","see"],"answer":2,"explanation":"Việc đã xem phim hai lần xảy ra trước quyết định không đi, trong bối cảnh quá khứ nên dùng had seen. Saw và have seen không thể hiện hành động xảy ra trước, see là hiện tại."}],"is_new":false},{"slug":"future-simple","stage":2,"position":7,"title":"Future Simple","title_en":"Future Simple (will)","summary":"Thì tương lai đơn với will dùng cho quyết định tức thời, lời hứa, lời đề nghị và dự đoán chủ quan. Công thức đơn giản là will + động từ nguyên mẫu.","content":"### Công thức\n\n- Khẳng định: **S + will + V** (will dùng cho mọi ngôi).\n- Phủ định: **S + will + not + V** (viết tắt won't + V).\n- Nghi vấn: **Will + S + V?** Trả lời ngắn: Yes, S + will. hoặc No, S + won't.\n\n### Cách dùng\n\n- Quyết định tức thời ngay lúc nói: The phone is ringing. I'll answer it (Điện thoại đang reo. Tôi sẽ nghe).\n- Dự đoán dựa trên suy nghĩ, không có bằng chứng rõ ràng: I think it will rain (Tôi nghĩ trời sẽ mưa).\n- Lời hứa, lời đề nghị, lời cảnh báo: I'll help you with that (Tôi sẽ giúp bạn việc đó).\n- Sự thật tương lai chắc chắn, không phụ thuộc kế hoạch: She will be 30 next year (Năm sau cô ấy sẽ 30 tuổi).\n\n### Dấu hiệu nhận biết\n\n- tomorrow, next week, next month, in 2030, soon.\n- I think, I hope, probably, perhaps, I promise.\n\n### Lỗi thường gặp\n\n- Thêm to sau will: I will to go sai, phải là I will go.\n- Dùng will trong mệnh đề when/if chỉ tương lai: When I will arrive sai, phải là When I arrive.\n- Dùng will cho kế hoạch đã sắp xếp sẵn, khi đó nên dùng be going to hoặc hiện tại tiếp diễn.","examples":[{"en":"I'll call you as soon as I arrive.","vi":"Tôi sẽ gọi cho bạn ngay khi tôi đến."},{"en":"I think our team will win the final.","vi":"Tôi nghĩ đội của chúng ta sẽ thắng trận chung kết."},{"en":"Don't worry, I won't tell anyone.","vi":"Đừng lo, tôi sẽ không nói với ai đâu."}],"exercises":[{"prompt":"Don't worry, I ___ you with the bags.","options":["help","will help","am helping","helped"],"answer":1,"explanation":"Đây là lời đề nghị đưa ra ngay lúc nói nên dùng will help. Help là hiện tại đơn, am helping chỉ việc đang làm, helped là quá khứ đơn."},{"prompt":"I think it ___ tomorrow.","options":["rains","will rain","is raining","rained"],"answer":1,"explanation":"I think thể hiện dự đoán chủ quan về tương lai nên dùng will rain. Rains và is raining chỉ hiện tại, rained là quá khứ."},{"prompt":"We ___ know the result until next Monday.","options":["will","won't","don't","aren't"],"answer":1,"explanation":"Until next Monday chỉ mốc tương lai, và nghĩa phủ định phù hợp với until: chúng tôi sẽ không biết kết quả cho đến thứ Hai. Will thiếu not, don't và aren't là hiện tại."}],"is_new":false},{"slug":"be-going-to-va-hien-tai-tiep-dien-tuong-lai","stage":2,"position":8,"title":"Be going to và Present Continuous chỉ tương lai","title_en":"Be going to and Present Continuous for future","summary":"Hai cấu trúc này đều nói về tương lai nhưng khác sắc thái: be going to cho dự định hoặc dự đoán có căn cứ, hiện tại tiếp diễn cho kế hoạch đã sắp xếp cụ thể.","content":"### Be going to\n\n- Khẳng định: **S + am/is/are + going to + V**; phủ định thêm not sau be; nghi vấn **Am/Is/Are + S + going to + V?**\n- Diễn tả dự định đã quyết định trước lúc nói: I'm going to buy a new laptop (Tôi định mua một chiếc laptop mới).\n- Dự đoán dựa trên bằng chứng hiện tại: Look at those clouds! It's going to rain (Nhìn mây kìa! Trời sắp mưa).\n\n### Present Continuous chỉ tương lai\n\n- Công thức: **S + am/is/are + V-ing** kèm thời gian tương lai.\n- Diễn tả kế hoạch, cuộc hẹn đã sắp xếp cụ thể với người khác: I'm meeting the doctor at 9 a.m tomorrow (Mai 9 giờ tôi có hẹn gặp bác sĩ).\n- Thường có thời gian, địa điểm rõ ràng hoặc vé, lịch đã đặt trước.\n\n### Phân biệt nhanh\n\n- will: quyết định ngay lúc nói, lời hứa, dự đoán chủ quan.\n- be going to: dự định có từ trước hoặc dự đoán có căn cứ nhìn thấy được.\n- Present Continuous: kế hoạch đã chốt, thường có sắp xếp với người khác.\n\n### Lỗi thường gặp\n\n- Dùng will cho cuộc hẹn đã đặt trước: kém tự nhiên, nên dùng hiện tại tiếp diễn.\n- Viết going to + V-ing: I'm going to meeting sai, phải là I'm going to meet.\n- Quên to be: She going to travel sai, phải là She is going to travel.","examples":[{"en":"Look at the sky! It's going to snow.","vi":"Nhìn trời kìa! Trời sắp có tuyết rơi."},{"en":"We're having dinner with my parents tonight.","vi":"Tối nay chúng tôi sẽ ăn tối với bố mẹ tôi."},{"en":"She's going to open a small shop next month.","vi":"Cô ấy định mở một cửa hàng nhỏ vào tháng sau."}],"exercises":[{"prompt":"Look at those black clouds! It ___ .","options":["rains","will rain","is going to rain","is raining"],"answer":2,"explanation":"Có bằng chứng nhìn thấy trước mắt nên dùng dự đoán với be going to: is going to rain. Will rain là dự đoán không căn cứ, rains và is raining chỉ hiện tại."},{"prompt":"I ___ my dentist at 10 a.m. tomorrow.","options":["see","will see","am seeing","am going see"],"answer":2,"explanation":"Đây là cuộc hẹn đã sắp xếp với thời gian cụ thể nên dùng hiện tại tiếp diễn am seeing. See là hiện tại đơn, will see kém tự nhiên cho lịch hẹn, am going see sai cấu trúc."},{"prompt":"I have already booked the tickets. I ___ to Hanoi on Friday.","options":["fly","will fly","am flying","would fly"],"answer":2,"explanation":"Vé đã đặt xong, tức kế hoạch đã chốt nên dùng am flying. Fly là hiện tại đơn, will fly không phù hợp với kế hoạch đã sắp xếp, would fly diễn tả điều kiện giả định."}],"is_new":true},{"slug":"future-continuous","stage":2,"position":9,"title":"Future Continuous","title_en":"Future Continuous","summary":"Thì tương lai tiếp diễn diễn tả hành động sẽ đang diễn ra tại một thời điểm xác định trong tương lai, hoặc một việc đã được sắp xếp sẵn.","content":"### Công thức\n\n- Khẳng định: **S + will be + V-ing**\n- Phủ định: **S + will not (won't) be + V-ing**\n- Nghi vấn: **Will + S + be + V-ing?**\n\n### Cách dùng\n\n- Diễn tả hành động đang diễn ra tại một thời điểm xác định trong tương lai: At 8 p.m. tomorrow, I will be watching the match (Lúc 8 giờ tối mai, tôi sẽ đang xem trận đấu).\n- Diễn tả việc đã được sắp xếp, sẽ diễn ra như một phần của lịch trình: This time next week, we will be flying to Japan (Tuần sau vào giờ này, chúng tôi sẽ đang bay tới Nhật).\n- Dùng để hỏi lịch sự về kế hoạch của người khác: Will you be using the car this afternoon? (Chiều nay bạn có dùng xe không?).\n- Nhấn mạnh quá trình đang tiếp diễn, khác với will + V chỉ nêu sự việc sẽ xảy ra.\n\n### Dấu hiệu nhận biết\n\n- at this time tomorrow, at 8 p.m. next Sunday, this time next week\n- all day tomorrow, at noon tomorrow\n- when / while + mệnh đề chia hiện tại đơn: While you are studying, I will be cleaning the house (Trong khi bạn học, tôi sẽ đang dọn nhà).\n\n### Lỗi thường gặp\n\n- Dùng will + V khi cần nhấn mạnh hành động đang diễn ra tại một mốc: At 9 a.m. tomorrow I will have a meeting chỉ nêu lịch, muốn nhấn đang diễn ra thì dùng I will be having a meeting.\n- Chia V-ing cho động từ trạng thái như know, believe, own; với các động từ này dùng will + V.\n- Chia will trong mệnh đề when / while: sai When you will arrive, I will be cooking.","examples":[{"en":"At this time tomorrow, I will be flying to Hanoi.","vi":"Vào giờ này ngày mai, tôi sẽ đang bay tới Hà Nội."},{"en":"Don't call me at eight tonight because I will be having dinner with my family.","vi":"Đừng gọi cho tôi lúc 8 giờ tối nay vì tôi sẽ đang ăn tối với gia đình."},{"en":"This time next month, they will be building the new bridge.","vi":"Tháng sau vào giờ này, họ sẽ đang thi công cây cầu mới."}],"exercises":[{"prompt":"At 9 a.m. tomorrow, she ___ a presentation to the board.","options":["gives","will give","will be giving","has given"],"answer":2,"explanation":"At 9 a.m. tomorrow là thời điểm xác định trong tương lai và hành động đang diễn ra lúc đó, nên dùng will be giving. Will give chỉ nêu sự việc sẽ xảy ra mà không nhấn quá trình; gives và has given sai mốc thời gian."},{"prompt":"Don't phone him at 7 p.m. because he ___ his piano lesson then.","options":["has","is having","will be having","had"],"answer":2,"explanation":"Then trỏ tới 7 p.m. trong tương lai, hành động đang diễn ra tại mốc đó nên cần will be having. Is having chỉ dùng cho hiện tại hoặc kế hoạch đã chốt, còn has và had sai thì."},{"prompt":"Will you ___ your car at 6 p.m. tomorrow? I need a lift.","options":["use","be using","have used","used"],"answer":1,"explanation":"Sau will cần be + V-ing để hỏi về việc xe đang được dùng tại một mốc tương lai. Use thiếu be, còn have used và used sai cấu trúc."}],"is_new":false},{"slug":"future-perfect","stage":2,"position":10,"title":"Future Perfect","title_en":"Future Perfect","summary":"Thì tương lai hoàn thành diễn tả hành động sẽ hoàn tất trước một mốc thời gian trong tương lai, nhấn mạnh kết quả.","content":"### Công thức\n\n- Khẳng định: **S + will have + V3/V-ed**\n- Phủ định: **S + will not (won't) have + V3/V-ed**\n- Nghi vấn: **Will + S + have + V3/V-ed?**\n- Bị động: **S + will have been + V3/V-ed**\n\n### Cách dùng\n\n- Diễn tả hành động sẽ hoàn thành trước một mốc thời gian trong tương lai: By the end of this month, we will have finished the report (Đến cuối tháng này, chúng tôi sẽ hoàn thành xong báo cáo).\n- Nhấn mạnh kết quả tại mốc đó, không quan tâm hành động kéo dài bao lâu.\n- Thường gặp với by the time + mệnh đề hiện tại đơn: By the time you come back, I will have painted the room (Trước khi bạn quay về, tôi sẽ sơn xong căn phòng).\n- Không dùng với mốc mơ hồ như someday, one day; những trạng từ này thường đi với tương lai đơn.\n\n### Dấu hiệu nhận biết\n\n- by + mốc tương lai: by 2030, by next Friday, by then\n- by the time, before + mốc thời gian\n- in + khoảng thời gian: in two years' time (trong hai năm nữa)\n\n### Lỗi thường gặp\n\n- Nhầm với tương lai tiếp diễn: will have + V3 cho việc đã hoàn thành, will be + V-ing cho việc đang diễn ra.\n- Chia will trong mệnh đề by the time: sai By the time you will arrive, đúng By the time you arrive.\n- Dùng will have + V-ing, dạng này không tồn tại; nếu nhấn thời lượng phải dùng will have been + V-ing.\n- Dùng sai cột bất quy tắc: sai will have wrote, đúng will have written.","examples":[{"en":"By the end of this year, I will have finished my master's degree.","vi":"Đến cuối năm nay, tôi sẽ hoàn thành xong bằng thạc sĩ."},{"en":"By the time the guests arrive, we will have prepared everything.","vi":"Trước khi khách tới, chúng tôi sẽ chuẩn bị xong mọi thứ."},{"en":"She will have saved enough money to buy a house by 2030.","vi":"Cô ấy sẽ tiết kiệm đủ tiền mua nhà trước năm 2030."}],"exercises":[{"prompt":"By next June, they ___ the new bridge.","options":["finish","will finish","will have finished","have finished"],"answer":2,"explanation":"By + mốc tương lai nhấn mạnh việc hoàn thành trước mốc đó nên dùng will have finished. Will finish chỉ nêu việc sẽ làm, không cho biết đã xong trước mốc hay chưa."},{"prompt":"The report ___ by the time the manager returns.","options":["finishes","will finish","will have been finished","is finishing"],"answer":2,"explanation":"Báo cáo là đối tượng bị hoàn thành nên cần bị động will have been + V3. Will finish ở dạng chủ động không hợp nghĩa, còn finishes và is finishing sai thì."},{"prompt":"By the end of the week, she ___ enough for the trip.","options":["saves","will save","will have saved","is saving"],"answer":2,"explanation":"Cụm by the end of the week là mốc tương lai và việc tiết kiệm phải xong trước mốc đó, nên dùng will have saved. Will save không thể hiện được ý hoàn tất trước mốc."}],"is_new":false},{"slug":"present-perfect-continuous","stage":2,"position":11,"title":"Present Perfect Continuous","title_en":"Present Perfect Continuous","summary":"Thì hiện tại hoàn thành tiếp diễn diễn tả hành động bắt đầu trong quá khứ, kéo dài đến hiện tại, nhấn mạnh quá trình và thời lượng.","content":"### Công thức\n\n- Khẳng định: **S + have/has been + V-ing**\n- Phủ định: **S + have/has not been + V-ing**\n- Nghi vấn: **Have/Has + S + been + V-ing?**\n\n### Cách dùng\n\n- Diễn tả hành động bắt đầu trong quá khứ, kéo dài đến hiện tại và có thể còn tiếp tục: I have been learning Japanese for two years (Tôi đã học tiếng Nhật được hai năm).\n- Nhấn mạnh quá trình và độ dài, khác hiện tại hoàn thành vốn nhấn kết quả: I have painted the wall (đã sơn xong) so với I have been painting the wall (còn đang sơn dở).\n- Giải thích nguyên nhân của một trạng thái hiện tại: Her eyes are red because she has been crying (Mắt cô ấy đỏ vì cô ấy vừa khóc).\n- Dùng với how long để hỏi về khoảng thời gian kéo dài: How long have you been waiting? (Bạn đã chờ bao lâu rồi?).\n\n### Dấu hiệu nhận biết\n\n- for + khoảng thời gian, since + mốc thời gian\n- all morning, all day, all week\n- lately, recently, how long\n\n### Lỗi thường gặp\n\n- Dùng thì này khi nêu số lần hoặc kết quả: sai I have been reading this book three times, đúng I have read this book three times.\n- Dùng với động từ trạng thái như know, like, own, believe; các động từ này chia ở hiện tại hoàn thành.\n- Nhầm since + mốc với for + khoảng thời gian: sai since two hours, đúng for two hours.\n- Chia hiện tại tiếp diễn dù có for / since: sai I am waiting for two hours, đúng I have been waiting for two hours.","examples":[{"en":"I have been waiting for the bus for twenty minutes.","vi":"Tôi đã chờ xe buýt được hai mươi phút rồi."},{"en":"She has been studying English since she was ten.","vi":"Cô ấy đã học tiếng Anh từ khi mười tuổi."},{"en":"The ground is wet because it has been raining all night.","vi":"Mặt đất ướt vì trời đã mưa suốt đêm."}],"exercises":[{"prompt":"How long ___ you ___ in this city?","options":["do / live","have / been living","are / living","did / live"],"answer":1,"explanation":"How long hỏi khoảng thời gian kéo dài đến hiện tại nên cần hiện tại hoàn thành tiếp diễn have been living. Do / live và are / living không diễn tả được sự kéo dài từ quá khứ."},{"prompt":"My eyes are red because I ___ at the screen all morning.","options":["stare","stared","have been staring","had stared"],"answer":2,"explanation":"All morning nối hành động kéo dài tới hiện tại và đang là nguyên nhân của trạng thái hiện tại, nên dùng have been staring. Stared và had stared đẩy sự việc vào quá khứ."},{"prompt":"He ___ three cups of coffee today.","options":["has been drinking","has drunk","is drinking","drinks"],"answer":1,"explanation":"Three cups là số lượng kết quả đã hoàn thành nên dùng hiện tại hoàn thành has drunk. Has been drinking nhấn quá trình, không phù hợp khi đếm số lần."}],"is_new":false},{"slug":"past-perfect-continuous","stage":2,"position":12,"title":"Past Perfect Continuous","title_en":"Past Perfect Continuous","summary":"Thì quá khứ hoàn thành tiếp diễn diễn tả hành động đã kéo dài liên tục trước một mốc hoặc một hành động khác trong quá khứ.","content":"### Công thức\n\n- Khẳng định: **S + had been + V-ing**\n- Phủ định: **S + had not been + V-ing**\n- Nghi vấn: **Had + S + been + V-ing?**\n\n### Cách dùng\n\n- Diễn tả hành động kéo dài liên tục trước một hành động hoặc mốc khác trong quá khứ: They had been driving for six hours before they stopped for lunch (Họ đã lái xe sáu tiếng trước khi dừng ăn trưa).\n- Nhấn mạnh quá trình kéo dài là nguyên nhân của một trạng thái trong quá khứ: He was out of breath because he had been running (Anh ấy thở hổn hển vì vừa chạy).\n- Thường xuất hiện trong câu có before, after, when, by the time với mệnh đề chia quá khứ đơn.\n- Khác quá khứ hoàn thành: had + V3 nhấn kết quả đã xong, had been + V-ing nhấn quá trình kéo dài.\n\n### Dấu hiệu nhận biết\n\n- before, after, when, by the time + mệnh đề quá khứ đơn\n- for + khoảng thời gian, since + mốc quá khứ\n- all day, all morning\n\n### Lỗi thường gặp\n\n- Nhầm had been + V-ing với had + V3 khi câu chỉ cần nêu kết quả.\n- Dùng với động từ trạng thái như know, belong, own.\n- Chia quá khứ đơn cho hành động xảy ra trước: sai When I arrived, he cooked for an hour, đúng When I arrived, he had been cooking for an hour.\n- Viết sai cấu trúc had been + V3 thay vì had been + V-ing.","examples":[{"en":"He had been working at the factory for ten years before he retired.","vi":"Ông ấy đã làm việc ở nhà máy mười năm trước khi nghỉ hưu."},{"en":"She was tired because she had been running for an hour.","vi":"Cô ấy mệt vì đã chạy suốt một tiếng đồng hồ."},{"en":"We had been waiting for two hours by the time the train arrived.","vi":"Chúng tôi đã chờ được hai tiếng khi tàu đến."}],"exercises":[{"prompt":"When I met her, she ___ in London for five years.","options":["lives","lived","had been living","has been living"],"answer":2,"explanation":"Việc sống ở London kéo dài năm năm trước thời điểm met trong quá khứ nên dùng had been living. Has been living nối tới hiện tại, còn lived không thể hiện được sự kéo dài trước."},{"prompt":"His hands were dirty because he ___ the car.","options":["repairs","repaired","had been repairing","has repaired"],"answer":2,"explanation":"Hành động sửa xe kéo dài trước và là nguyên nhân của trạng thái tay bẩn trong quá khứ, nên dùng had been repairing. Repaired chỉ nêu một việc đã xảy ra, không nhấn quá trình."},{"prompt":"She ___ all day, so she went to bed early.","options":["had been cleaning","has been cleaning","cleans","cleaned"],"answer":0,"explanation":"Việc dọn dẹp kéo dài suốt ngày trước khi cô ấy đi ngủ trong quá khứ, nên dùng had been cleaning. Has been cleaning kéo tới hiện tại nên không khớp với went."}],"is_new":false},{"slug":"future-perfect-continuous","stage":2,"position":13,"title":"Future Perfect Continuous","title_en":"Future Perfect Continuous","summary":"Thì tương lai hoàn thành tiếp diễn diễn tả hành động sẽ kéo dài liên tục đến một mốc trong tương lai, nhấn mạnh thời lượng.","content":"### Công thức\n\n- Khẳng định: **S + will have been + V-ing**\n- Phủ định: **S + will not (won't) have been + V-ing**\n- Nghi vấn: **Will + S + have been + V-ing?**\n\n### Cách dùng\n\n- Diễn tả hành động sẽ kéo dài liên tục đến một mốc trong tương lai, nhấn mạnh thời lượng: By next month, I will have been teaching here for ten years (Đến tháng sau, tôi sẽ dạy ở đây được mười năm).\n- Thường đi kèm by + mốc tương lai và for + khoảng thời gian để làm rõ độ dài.\n- Có thể dùng để nói về nguyên nhân của một trạng thái trong tương lai, nhưng cách dùng này ít gặp.\n- Khác tương lai hoàn thành: will have + V3 nhấn kết quả đã xong, will have been + V-ing nhấn quá trình kéo dài.\n\n### Dấu hiệu nhận biết\n\n- by + mốc tương lai + for + khoảng thời gian: by 2030, for fifteen years\n- by the time + mệnh đề hiện tại đơn + for + khoảng thời gian\n- when + mệnh đề hiện tại đơn, đi cùng một khoảng thời gian kéo dài\n\n### Lỗi thường gặp\n\n- Nhầm với will have + V3: nếu câu có for + khoảng thời gian và nhấn kéo dài thì phải dùng will have been + V-ing.\n- Chia will trong mệnh đề by the time: sai By the time you will finish, đúng By the time you finish.\n- Dùng với động từ trạng thái như know, own, belong.\n- Viết sai trật tự: sai will be have been working, đúng will have been working.","examples":[{"en":"By next month, I will have been teaching here for ten years.","vi":"Đến tháng sau, tôi sẽ dạy ở đây được mười năm."},{"en":"When you arrive, she will have been driving for eight hours.","vi":"Khi bạn tới, cô ấy sẽ đã lái xe được tám tiếng."},{"en":"By the end of the day, they will have been painting the house for a week.","vi":"Đến cuối ngày, họ sẽ sơn nhà được một tuần."}],"exercises":[{"prompt":"By December, we ___ this course for six months.","options":["take","will take","will have been taking","have taken"],"answer":2,"explanation":"By December là mốc tương lai, còn for six months nhấn thời lượng kéo dài đến mốc đó nên cần will have been taking. Will take không diễn tả được sự kéo dài."},{"prompt":"By the time the movie ends, he ___ for three hours.","options":["sleeps","will sleep","will have been sleeping","has slept"],"answer":2,"explanation":"Hành động ngủ kéo dài ba tiếng tính đến lúc phim kết thúc trong tương lai, nên dùng will have been sleeping. Will sleep chỉ nêu việc sẽ ngủ, không nêu thời lượng."},{"prompt":"When the new manager starts, she ___ with the company for a decade.","options":["works","worked","will have been working","has worked"],"answer":2,"explanation":"Mệnh đề when chia hiện tại đơn để nói tương lai, còn for a decade nhấn quá trình kéo dài đến lúc đó nên dùng will have been working. Has worked gắn với hiện tại nên sai."}],"is_new":false},{"slug":"used-to-would","stage":2,"position":14,"title":"Used to / Would (thói quen trong quá khứ)","title_en":"Used to / Would for past habits","summary":"Used to và would dùng để kể về thói quen hoặc trạng thái trong quá khứ; used to dùng được cho cả trạng thái, còn would chỉ dùng cho hành động lặp lại.","content":"### Công thức\n\n- **S + used to + V** (đã từng làm gì, nay không còn)\n- **S + did not (didn't) use to + V** / **Did + S + use to + V?**\n- **S + would + V** (thói quen trong quá khứ, thường để hồi tưởng)\n- **S + be/get used to + V-ing** (quen với việc gì, nghĩa khác hoàn toàn)\n\n### Cách dùng\n\n- Used to diễn tả thói quen hoặc trạng thái trong quá khứ và hàm ý hiện tại không còn: I used to live in a small village (Tôi từng sống ở một ngôi làng nhỏ).\n- Would chỉ dùng cho hành động lặp lại, không dùng cho trạng thái: sai I would have a dog, đúng I used to have a dog.\n- Would thường xuất hiện trong câu kể chuyện, gợi không khí hồi tưởng: Every summer, we would visit our grandparents (Mỗi mùa hè, chúng tôi lại về thăm ông bà).\n- Be used to + V-ing diễn tả trạng thái quen với việc gì ở hiện tại: I am used to getting up early (Tôi đã quen dậy sớm).\n\n### Dấu hiệu nhận biết\n\n- when I was a child, in those days, years ago, back then\n- every summer, every evening, whenever + mệnh đề quá khứ\n\n### Lỗi thường gặp\n\n- Thêm -ing sau used to: sai I used to playing football, đúng I used to play football.\n- Viết didn't used to; dạng đúng là didn't use to.\n- Dùng would với động từ trạng thái như have, know, live, be.\n- Nhầm used to (đã từng) với be used to (quen với).","examples":[{"en":"My grandfather used to tell us stories every evening.","vi":"Ông tôi thường kể chuyện cho chúng tôi nghe mỗi tối."},{"en":"When I was a student, I would ride my bike to school every day.","vi":"Khi còn là sinh viên, ngày nào tôi cũng đạp xe đến trường."},{"en":"There used to be a small market on this corner.","vi":"Trước đây từng có một khu chợ nhỏ ở góc phố này."}],"exercises":[{"prompt":"My sister ___ short hair when she was little, but now it's long.","options":["used to have","would have","is used to having","uses to have"],"answer":0,"explanation":"Have short hair là trạng thái trong quá khứ nên phải dùng used to have. Would không dùng với trạng thái, is used to having nói về hiện tại, còn uses to have sai cấu trúc."},{"prompt":"In those days, my father ___ home late every night.","options":["would come","is coming","has come","is used to coming"],"answer":0,"explanation":"Come home là hành động lặp lại trong quá khứ, có in those days làm mốc, nên would come phù hợp. Is coming và has come thuộc hiện tại, is used to coming diễn tả thói quen hiện tại."},{"prompt":"I ___ getting up early now, but it was hard at first.","options":["used to","am used to","would","use to"],"answer":1,"explanation":"Câu nói về việc đã quen với dậy sớm ở hiện tại nên cần am used to + V-ing. Used to và would chỉ dùng cho quá khứ, còn use to thiếu trợ động từ."}],"is_new":true},{"slug":"on-tap-so-sanh-cac-thi","stage":2,"position":15,"title":"Ôn tập và so sánh các thì","title_en":"Tense review and contrast","summary":"Hệ thống lại cách chọn thì dựa trên mốc thời gian, trạng thái hành động và từ tín hiệu, đồng thời phân biệt các cặp thì dễ nhầm.","content":"### Nguyên tắc chọn thì\n\n- Bước 1: xác định mốc thời gian của câu là quá khứ, hiện tại hay tương lai.\n- Bước 2: xác định hành động đang diễn ra, đã hoàn thành hay lặp lại thành thói quen.\n- Bước 3: đối chiếu từ tín hiệu trong câu để chốt thì.\n\n### Các cặp dễ nhầm\n\n- Quá khứ đơn và hiện tại hoàn thành: quá khứ đơn gắn với mốc đã kết thúc (yesterday, in 2019, last week); hiện tại hoàn thành nối với hiện tại (since, for, already, yet, ever).\n- Hiện tại hoàn thành và hiện tại hoàn thành tiếp diễn: thì đầu nhấn kết quả hoặc số lần, thì sau nhấn quá trình và độ dài.\n- Quá khứ đơn và quá khứ hoàn thành: hành động xảy ra trước dùng had + V3, hành động xảy ra sau dùng quá khứ đơn.\n- Will, be going to và hiện tại tiếp diễn: will cho quyết định tức thời hoặc dự đoán; be going to cho dự định trước hoặc dự đoán có bằng chứng; hiện tại tiếp diễn cho lịch hẹn đã sắp xếp.\n- Will have + V3 và will have been + V-ing: thì thứ nhất nhấn hoàn thành trước mốc, thì thứ hai nhấn kéo dài đến mốc.\n- Used to và would: used to dùng cho cả trạng thái và thói quen, would chỉ dùng cho hành động lặp lại.\n\n### Chiến lược làm bài\n\n- Gạch chân từ tín hiệu thời gian trước khi nhìn đáp án.\n- Loại đáp án sai mốc thời gian trước, rồi mới xét tiếp diễn hay hoàn thành.\n- Với câu có hai hành động, xác định việc nào xảy ra trước.\n\n### Lỗi thường gặp\n\n- Thấy since hoặc for là chọn ngay hiện tại hoàn thành tiếp diễn, bỏ qua động từ trạng thái.\n- Bỏ qua bằng chứng ở hiện tại khi cân nhắc be going to.\n- Dùng hiện tại hoàn thành với mốc quá khứ đã kết thúc: sai I have seen him yesterday.","examples":[{"en":"I have lived in this city for ten years, but my brother moved away in 2019.","vi":"Tôi đã sống ở thành phố này mười năm, nhưng anh trai tôi đã chuyển đi năm 2019."},{"en":"She had been cooking for two hours when the guests arrived.","vi":"Cô ấy đã nấu ăn được hai tiếng khi khách tới."},{"en":"Next year, I will have been working here for a decade.","vi":"Năm sau, tôi sẽ làm việc ở đây được mười năm."}],"exercises":[{"prompt":"I ___ my keys yesterday, so I can't get into the house now.","options":["lose","lost","have lost","had lost"],"answer":1,"explanation":"Yesterday là mốc quá khứ đã kết thúc nên phải dùng quá khứ đơn lost. Have lost tuy diễn tả kết quả hiện tại nhưng không đi với mốc quá khứ xác định."},{"prompt":"Look at those dark clouds! It ___.","options":["rains","rained","is going to rain","has rained"],"answer":2,"explanation":"Câu có bằng chứng trực tiếp ở hiện tại là những đám mây đen nên dùng be going to để dự đoán. Rains và has rained không hợp ngữ cảnh, rained sai mốc thời gian."},{"prompt":"By the time we got to the cinema, the film ___.","options":["starts","started","had started","has started"],"answer":2,"explanation":"Phim đã bắt đầu trước khi chúng tôi tới rạp, hai việc đều trong quá khứ, nên hành động xảy ra trước dùng had started. Started không thể hiện được thứ tự trước sau."}],"is_new":true},{"slug":"modal-verbs","stage":3,"position":1,"title":"Modal verbs","title_en":"Modal verbs","summary":"Động từ khuyết thiếu diễn tả khả năng, nghĩa vụ, lời khuyên và sự cho phép; không chia theo ngôi và luôn đi với động từ nguyên mẫu.","content":"### Công thức\n\nĐộng từ khuyết thiếu (modal verbs) đứng trước động từ chính ở dạng nguyên mẫu không \"to\": **S + modal + V (bare) + O**. Modal không chia theo ngôi, không thêm -s, -ed hay -ing. Câu phủ định thêm **not** sau modal; câu hỏi đảo modal lên đầu câu.\n\n- She can swim. (Cô ấy biết bơi.)\n- He cannot come today. (Anh ấy không thể đến hôm nay.)\n- Should we leave now? (Chúng ta có nên đi ngay không?)\n\n### Các modal thông dụng\n\n- **can / could**: khả năng, xin phép; could lịch sự hơn hoặc chỉ khả năng trong quá khứ.\n- **may / might**: xin phép trang trọng hoặc dự đoán khả năng; might ít chắc chắn hơn.\n- **must**: bắt buộc theo ý người nói; **have to** là bắt buộc do hoàn cảnh.\n- **should / ought to**: đưa lời khuyên.\n- **will / would**: dự đoán, lời hứa, lời mời.\n\n### Cách dùng\n\n- Diễn tả khả năng: I can speak a little Japanese. (Tôi nói được một chút tiếng Nhật.)\n- Diễn tả nghĩa vụ: Visitors must sign in at reception. (Khách phải ký tên ở quầy lễ tân.)\n- Đưa lời khuyên: You should get more sleep. (Bạn nên ngủ nhiều hơn.)\n- Phân biệt **mustn't** (bị cấm) với **don't have to** (không cần thiết): You mustn't smoke here. / You don't have to come early.\n\n### Lỗi thường gặp\n\n- Không thêm \"to\" sau modal: nói *She can swims* là sai, đúng là **She can swim**.\n- Không dùng hai modal liền nhau; thay bằng cụm tương đương như **will be able to** thay cho *will can*.\n- Không thêm -s ở ngôi thứ ba: **He must go**, không phải *He musts go*.","examples":[{"en":"You must wear a helmet when you ride a motorbike.","vi":"Bạn phải đội mũ bảo hiểm khi đi xe máy."},{"en":"Students may use the library until nine p.m.","vi":"Sinh viên có thể dùng thư viện đến chín giờ tối."},{"en":"We should book the tickets early.","vi":"Chúng ta nên đặt vé sớm."}],"exercises":[{"prompt":"You ___ park here; it is a no-parking zone.","options":["must","mustn't","don't have to","should"],"answer":1,"explanation":"Biển cấm đỗ xe nên dùng mustn't (bị cấm). must nghĩa là phải đỗ, don't have to là không cần thiết, should là lời khuyên nên không hợp nghĩa."},{"prompt":"She ___ speak three languages when she was ten.","options":["can","could","must","should"],"answer":1,"explanation":"Có mốc quá khứ when she was ten nên dùng could để chỉ khả năng trong quá khứ. can chỉ khả năng hiện tại, must và should không diễn tả khả năng."},{"prompt":"It is raining heavily. You ___ take an umbrella.","options":["should","shouldn't","mustn't","can't"],"answer":0,"explanation":"Đây là lời khuyên nên dùng should. shouldn't là không nên, mustn't là bị cấm, can't là không thể nên đều sai nghĩa."}],"is_new":false},{"slug":"cum-gioi-tu","stage":3,"position":2,"title":"Cụm giới từ","title_en":"Prepositional phrases, time and place","summary":"Nắm cách dùng in/on/at cho thời gian và nơi chốn, cùng các cụm giới từ cố định thường gặp trong giao tiếp và bài thi.","content":"### Giới từ chỉ thời gian: in, on, at\n\n- **in** dùng với khoảng thời gian dài: tháng, năm, mùa, thế kỷ — in July, in 2024, in winter.\n- **on** dùng với ngày và thứ cụ thể — on Monday, on 2 September, on my birthday.\n- **at** dùng với giờ và dịp ngắn — at 7 a.m., at noon, at Christmas.\n- **for** chỉ khoảng thời gian (for two hours), **since** chỉ mốc bắt đầu (since 2015).\n\n### Giới từ chỉ nơi chốn\n\n- **in**: bên trong không gian hoặc khu vực lớn — in the box, in Hanoi.\n- **on**: trên bề mặt, có tiếp xúc — on the table, on the wall.\n- **at**: tại một điểm cụ thể — at the bus stop, at the door.\n- **under, behind, between, next to, opposite, near** mô tả vị trí tương đối giữa các vật.\n\n### Cụm giới từ thông dụng\n\nCụm giới từ là nhóm **giới từ + danh từ/đại từ**, thường làm trạng ngữ hoặc bổ nghĩa cho động từ, tính từ.\n\n- in the morning (vào buổi sáng), at night (vào ban đêm), on time (đúng giờ), in time (kịp lúc).\n- by bus (bằng xe buýt), on foot (đi bộ), with a pen (bằng bút).\n- interested in (quan tâm đến), good at (giỏi về), afraid of (sợ), depend on (phụ thuộc vào).\n\n### Lỗi thường gặp\n\n- Nhầm **in/on/at**: nói *in Monday* là sai, đúng là **on Monday**; *at 2024* sai, đúng là **in 2024**.\n- Dùng **since** với khoảng thời gian: *since three years* sai, đúng là **for three years**.\n- Bỏ mất giới từ cố định sau tính từ hoặc động từ: **listen to music**, không phải *listen music*.\n\n### Mẹo ghi nhớ\n\nHọc giới từ theo cả cụm thay vì học từng từ riêng lẻ; ghi kèm một câu ví dụ để nhớ ngữ cảnh sử dụng.","examples":[{"en":"The meeting starts at nine o'clock on Monday.","vi":"Cuộc họp bắt đầu lúc chín giờ vào thứ Hai."},{"en":"She has lived in Hanoi since 2015.","vi":"Cô ấy đã sống ở Hà Nội từ năm 2015."},{"en":"The keys are in the top drawer.","vi":"Chìa khóa ở trong ngăn kéo trên cùng."}],"exercises":[{"prompt":"The meeting starts ___ 9 a.m. ___ Monday.","options":["in / on","at / on","on / at","at / in"],"answer":1,"explanation":"Giờ cụ thể dùng at, ngày cụ thể dùng on. Các phương án còn lại đặt sai giới từ cho giờ hoặc cho thứ."},{"prompt":"She has lived in Hanoi ___ 2015.","options":["for","since","in","at"],"answer":1,"explanation":"since dùng với mốc thời gian bắt đầu (2015). for dùng với khoảng thời gian, in và at không phù hợp với mốc bắt đầu."},{"prompt":"The keys are ___ the drawer.","options":["in","on","at","by"],"answer":0,"explanation":"Vật nằm bên trong ngăn kéo nên dùng in. on chỉ bề mặt, at chỉ điểm cụ thể, by nghĩa là bên cạnh."}],"is_new":true},{"slug":"to-infinitive-va-v-ing","stage":3,"position":3,"title":"To-infinitive và V-ing","title_en":"To-infinitive and V-ing","summary":"Phân biệt khi nào dùng to + động từ nguyên mẫu và khi nào dùng V-ing, kèm nhóm động từ đổi nghĩa theo hình thức.","content":"### Công thức\n\n- **to + V (nguyên mẫu)**: I want to learn Spanish. (Tôi muốn học tiếng Tây Ban Nha.)\n- **V-ing (danh động từ)**: I enjoy learning languages. (Tôi thích học ngôn ngữ.)\n- Cả hai đều có thể làm chủ ngữ, tân ngữ hoặc bổ ngữ: To travel is exciting. / Traveling is exciting.\n\n### Động từ theo sau là to-infinitive\n\n- Nhóm ý định, quyết định: **decide, plan, hope, want, need, agree, refuse, promise, offer**.\n- She decided to change her job. (Cô ấy quyết định đổi việc.)\n- They promised to help us. (Họ hứa sẽ giúp chúng tôi.)\n- Sau tính từ thường dùng to-infinitive: It is important to practise daily. (Việc luyện tập hằng ngày là quan trọng.)\n\n### Động từ theo sau là V-ing\n\n- Nhóm thích, tránh, kết thúc: **enjoy, like, love, hate, avoid, finish, mind, suggest, keep**.\n- He avoids driving at night. (Anh ấy tránh lái xe ban đêm.)\n- We finished cleaning the room. (Chúng tôi đã dọn xong phòng.)\n- Sau giới từ luôn dùng V-ing: She is good at cooking. (Cô ấy nấu ăn giỏi.)\n\n### Động từ đổi nghĩa\n\n- **stop to do**: dừng lại để làm việc gì; **stop doing**: từ bỏ việc gì.\n- **remember/forget to do**: nhớ hoặc quên phải làm; **remember/forget doing**: nhớ hoặc quên đã làm.\n- **try to do**: cố gắng làm; **try doing**: thử làm một cách khác.\n\n### Lỗi thường gặp\n\n- Dùng sai dạng sau giới từ: *interested in read* sai, đúng là **interested in reading**.\n- Thêm \"to\" sau modal hoặc sau **make/let**: **Let me go**, không phải *Let me to go*.\n- Học thuộc máy móc một động từ mà không chú ý nghĩa, dẫn đến chọn sai dạng khi nghĩa thay đổi.","examples":[{"en":"I want to improve my English this year.","vi":"Tôi muốn cải thiện tiếng Anh của mình trong năm nay."},{"en":"She avoids eating late at night.","vi":"Cô ấy tránh ăn muộn vào ban đêm."},{"en":"They plan to travel to Da Nang next month.","vi":"Họ dự định đi Đà Nẵng vào tháng sau."}],"exercises":[{"prompt":"I enjoy ___ books before bed.","options":["read","to read","reading","reads"],"answer":2,"explanation":"enjoy luôn đi với V-ing nên dùng reading. to read và read không đúng sau enjoy, reads là dạng chia theo ngôi nên càng sai."},{"prompt":"She decided ___ a new job.","options":["applying for","to apply for","apply for","applied for"],"answer":1,"explanation":"decide đi với to-infinitive nên chọn to apply for. applying for đứng sau giới từ, apply for thiếu to, applied for là dạng quá khứ."},{"prompt":"He stopped ___ two years ago and has been healthier since then.","options":["to smoke","smoking","smoke","smoked"],"answer":1,"explanation":"stop smoking nghĩa là từ bỏ hút thuốc, phù hợp với việc khỏe hơn. stop to smoke nghĩa là dừng lại để hút thuốc, trái với ngữ cảnh."}],"is_new":false},{"slug":"so-sanh","stage":3,"position":4,"title":"So sánh","title_en":"Comparisons","summary":"Ba dạng so sánh cơ bản trong tiếng Anh: bằng, hơn và nhất, cùng quy tắc thêm -er/-est hoặc more/most.","content":"### So sánh bằng\n\n**S + be/V + as + adj/adv + as + noun/pronoun**\n\n- This room is as large as that one. (Phòng này rộng bằng phòng kia.)\n- Phủ định: **not as/so ... as** — He doesn't run as fast as his brother. (Anh ấy không chạy nhanh bằng anh trai.)\n- Với danh từ đếm được dùng **as many ... as**, không đếm được dùng **as much ... as**.\n\n### So sánh hơn\n\n- Tính từ ngắn: **adj + -er + than** — Hanoi is colder than Saigon in winter. (Hà Nội lạnh hơn Sài Gòn vào mùa đông.)\n- Tính từ dài: **more + adj + than** — This book is more interesting than that one. (Cuốn sách này thú vị hơn cuốn kia.)\n- Trạng từ: **more slowly**, **faster**; bất quy tắc: good → better, bad → worse, far → farther/further.\n\n### So sánh nhất\n\n- Ngắn: **the + adj + -est** — She is the tallest girl in the class. (Cô ấy là cô gái cao nhất lớp.)\n- Dài: **the most + adj** — This is the most expensive phone in the shop. (Đây là chiếc điện thoại đắt nhất cửa hàng.)\n- Bất quy tắc: best, worst, farthest. Thường dùng với **in** (phạm vi) hoặc **of** (nhóm).\n\n### Lỗi thường gặp\n\n- Dùng cả -er và more: *more cheaper* sai, đúng là **cheaper**.\n- Thiếu \"than\" trong so sánh hơn hoặc thiếu \"the\" trước so sánh nhất.\n- Nhân đôi phụ âm sai: big → **bigger**, hot → **hotter**, nhưng happy → **happier**.\n\n### Mẹo\n\nĐếm âm tiết để chọn -er/-est hay more/most; học thuộc các dạng bất quy tắc và luôn kiểm tra lại đuôi tính từ.","examples":[{"en":"Mount Everest is the highest mountain in the world.","vi":"Everest là ngọn núi cao nhất trên thế giới."},{"en":"Today is hotter than yesterday.","vi":"Hôm nay nóng hơn hôm qua."},{"en":"This exercise is as easy as the previous one.","vi":"Bài tập này dễ như bài trước."}],"exercises":[{"prompt":"This hotel is ___ than the one we stayed in last year.","options":["cheap","cheaper","cheapest","more cheap"],"answer":1,"explanation":"Có than nên cần so sánh hơn; cheap là tính từ ngắn nên dùng cheaper. cheap là dạng gốc, cheapest là so sánh nhất, more cheap sai vì vừa dùng more vừa dùng tính từ ngắn."},{"prompt":"She is the ___ student in her class.","options":["intelligent","more intelligent","most intelligent","intelligenter"],"answer":2,"explanation":"Có the và phạm vi in her class nên dùng so sánh nhất; intelligent là tính từ dài nên chọn most intelligent. more intelligent là so sánh hơn, intelligenter không tồn tại."},{"prompt":"My phone is not as ___ as yours.","options":["expensive","more expensive","most expensive","expensiver"],"answer":0,"explanation":"Cấu trúc so sánh bằng là as + tính từ gốc + as, nên dùng expensive. more expensive và most expensive không đứng trong cấu trúc as ... as, expensiver sai vì tính từ dài."}],"is_new":false},{"slug":"cau-bi-dong-co-ban","stage":3,"position":5,"title":"Câu bị động cơ bản","title_en":"Basic passive voice","summary":"Chuyển câu chủ động sang bị động với công thức be + V3, chia theo thì và lược bỏ tác nhân khi không cần thiết.","content":"### Công thức\n\nCâu bị động nhấn mạnh người hoặc vật nhận hành động:\n\n**S + be + V3/ed (+ by + O)**\n\n- Chủ động: The chef cooked the meal. → Bị động: The meal was cooked by the chef. (Bữa ăn được đầu bếp nấu.)\n- Tân ngữ của câu chủ động trở thành chủ ngữ câu bị động; \"by + tác nhân\" có thể lược bỏ khi không quan trọng.\n\n### Chia thì\n\n- Hiện tại đơn: **am/is/are + V3** — English is spoken worldwide. (Tiếng Anh được nói trên toàn thế giới.)\n- Quá khứ đơn: **was/were + V3** — The letter was sent yesterday. (Lá thư được gửi hôm qua.)\n- Hiện tại hoàn thành: **has/have been + V3** — The room has been cleaned. (Căn phòng đã được dọn.)\n- Tương lai đơn: **will be + V3** — The results will be announced tomorrow. (Kết quả sẽ được công bố ngày mai.)\n- Modal: **modal + be + V3** — This form must be signed. (Biểu mẫu này phải được ký.)\n\n### Cách dùng\n\n- Khi không biết hoặc không cần nêu người thực hiện: My bike was stolen last night. (Xe đạp của tôi bị lấy cắp tối qua.)\n- Khi muốn nhấn mạnh đối tượng chịu tác động: The tree was planted by students. (Cây được trồng bởi sinh viên.)\n- Trong văn phong trang trọng, khoa học và tin tức.\n\n### Lỗi thường gặp\n\n- Quên đổi động từ thành V3: *The house was build* sai, đúng là **was built**.\n- Giữ nguyên tân ngữ sau động từ bị động: *It was sent the email* sai; đúng là **The email was sent**.\n- Chia sai \"be\" theo thì hoặc theo số ít, số nhiều của chủ ngữ.","examples":[{"en":"The house was built in 1990.","vi":"Ngôi nhà được xây vào năm 1990."},{"en":"The emails are checked every morning.","vi":"Email được kiểm tra mỗi buổi sáng."},{"en":"A new policy will be announced tomorrow.","vi":"Một chính sách mới sẽ được công bố vào ngày mai."}],"exercises":[{"prompt":"The report ___ by the manager yesterday.","options":["wrote","was written","is written","has written"],"answer":1,"explanation":"Báo cáo nhận hành động và có mốc yesterday nên dùng bị động quá khứ was written. wrote và has written là chủ động, is written sai thì."},{"prompt":"English ___ in many countries around the world.","options":["speaks","is speaking","is spoken","has spoken"],"answer":2,"explanation":"Tiếng Anh được nói bởi nhiều người nên cần bị động hiện tại is spoken. speaks và has spoken là chủ động, is speaking là tiếp diễn chủ động."},{"prompt":"The new bridge ___ next year.","options":["will build","will be built","is building","built"],"answer":1,"explanation":"Cây cầu nhận hành động xây và có mốc tương lai nên dùng will be built. will build và built là chủ động, is building sai thì và sai thể."}],"is_new":false},{"slug":"cau-dieu-kien-loai-0","stage":3,"position":6,"title":"Câu điều kiện loại 0","title_en":"Zero conditional","summary":"Diễn tả sự thật hiển nhiên, quy luật tự nhiên và thói quen luôn đúng, với cả hai vế chia ở hiện tại đơn.","content":"### Công thức\n\n**If + S + V (hiện tại đơn), S + V (hiện tại đơn)**\n\n- If you heat water to 100°C, it boils. (Nếu bạn đun nước đến 100°C, nó sôi.)\n- Có thể đảo hai mệnh đề: It boils if you heat water to 100°C.\n- Mệnh đề if có thể dùng **when** với nghĩa tương tự khi nói về quy luật.\n\n### Cách dùng\n\n- Diễn tả sự thật hiển nhiên, quy luật tự nhiên hoặc thói quen luôn đúng.\n- If plants don't get sunlight, they die. (Nếu cây không nhận ánh sáng, chúng sẽ chết.)\n- If I stay up late, I feel tired the next day. (Nếu tôi thức khuya, hôm sau tôi thấy mệt.)\n- Cả hai vế đều dùng thì hiện tại; không dùng will ở mệnh đề if.\n\n### Dấu hiệu nhận biết\n\n- Câu nói về quy luật, sự thật chung hoặc hướng dẫn vận hành.\n- Thường gặp **if/when + hiện tại đơn**, kết quả cũng ở hiện tại đơn.\n- Có thể dùng mệnh lệnh ở vế sau: If you feel sick, see a doctor. (Nếu bạn thấy mệt, hãy đi khám bác sĩ.)\n\n### Lỗi thường gặp\n\n- Dùng will ở mệnh đề if: *If it will rain* sai, đúng là **If it rains**.\n- Dùng thì quá khứ cho một sự thật hiển nhiên.\n- Nhầm với câu điều kiện loại 1: loại 0 nói quy luật chung, loại 1 nói tình huống cụ thể trong tương lai.\n\n### Mẹo\n\nNếu câu có thể thay if bằng when mà nghĩa không đổi, đó thường là câu điều kiện loại 0.","examples":[{"en":"If you mix red and blue, you get purple.","vi":"Nếu bạn trộn đỏ với xanh dương, bạn sẽ được màu tím."},{"en":"Water boils if you heat it to 100 degrees Celsius.","vi":"Nước sôi nếu bạn đun đến 100 độ C."},{"en":"If I drink coffee at night, I cannot sleep.","vi":"Nếu tôi uống cà phê vào ban đêm, tôi không ngủ được."}],"exercises":[{"prompt":"If you heat ice, it ___.","options":["melts","will melt","melted","would melt"],"answer":0,"explanation":"Đây là quy luật tự nhiên nên cả hai vế dùng hiện tại đơn, chọn melts. will melt, melted và would melt đều không phù hợp với câu điều kiện loại 0."},{"prompt":"If she ___ late, she misses the bus.","options":["is","will be","was","would be"],"answer":0,"explanation":"Câu điều kiện loại 0 dùng hiện tại đơn ở mệnh đề if nên chọn is. will be không dùng sau if trong loại 0, was và would be sai thì."},{"prompt":"Plants die if they ___ enough water.","options":["don't get","won't get","didn't get","wouldn't get"],"answer":0,"explanation":"Quy luật chung nên mệnh đề if dùng hiện tại đơn phủ định don't get. won't get, didn't get và wouldn't get đều sai thì so với câu điều kiện loại 0."}],"is_new":false},{"slug":"cau-dieu-kien-loai-1","stage":3,"position":7,"title":"Câu điều kiện loại 1","title_en":"First conditional","summary":"Diễn tả tình huống có thể xảy ra trong tương lai và kết quả của nó, với if + hiện tại đơn và will + động từ nguyên mẫu.","content":"### Công thức\n\n**If + S + V (hiện tại đơn), S + will/can/may + V (nguyên mẫu)**\n\n- If it rains tomorrow, we will cancel the trip. (Nếu mai trời mưa, chúng tôi sẽ hủy chuyến đi.)\n- Mệnh đề chính có thể dùng **can, may, should, must** thay cho will tùy mức độ chắc chắn.\n- Có thể đảo hai mệnh đề: We will cancel the trip if it rains tomorrow.\n\n### Cách dùng\n\n- Diễn tả khả năng có thể xảy ra trong tương lai và kết quả của nó.\n- If you study hard, you will pass the exam. (Nếu bạn học chăm, bạn sẽ đỗ.)\n- Dùng để đưa ra lời hứa, cảnh báo hoặc đề nghị: If you need help, I will call you. (Nếu bạn cần giúp, tôi sẽ gọi cho bạn.)\n- **Unless** = if not: Unless you hurry, you will be late. (Trừ khi bạn nhanh lên, bạn sẽ bị muộn.)\n\n### Biến thể\n\n- Mệnh đề if có thể dùng hiện tại tiếp diễn hoặc hiện tại hoàn thành: If you are waiting for the bus, I will join you. (Nếu bạn đang đợi xe buýt, tôi sẽ tham gia cùng.)\n- Mệnh đề chính có thể là mệnh lệnh: If you see her, tell her the news. (Nếu bạn gặp cô ấy, hãy kể cho cô ấy tin đó.)\n- Không dùng will ở mệnh đề if, trừ khi if mang nghĩa \"nếu bạn sẵn lòng\": If you will help me, we can finish early.\n\n### Lỗi thường gặp\n\n- *If it will rain, I will stay home* sai; đúng là **If it rains, I will stay home**.\n- Dùng unless kèm phủ định: *Unless you don't hurry* sai; đúng là **Unless you hurry**.\n- Chia sai thì ở mệnh đề chính, chẳng hạn dùng V-ing hoặc thì quá khứ.\n\n### Mẹo\n\nXác định tình huống chỉ là khả năng trong tương lai thì chọn loại 1; nếu là quy luật luôn đúng thì chuyển sang loại 0.","examples":[{"en":"If you finish early, we will go for a walk.","vi":"Nếu bạn xong sớm, chúng ta sẽ đi dạo."},{"en":"Unless you hurry, you will miss the train.","vi":"Trừ khi bạn nhanh lên, bạn sẽ lỡ chuyến tàu."},{"en":"If I see him, I will tell him the news.","vi":"Nếu tôi gặp anh ấy, tôi sẽ kể cho anh ấy tin đó."}],"exercises":[{"prompt":"If it ___ tomorrow, we will stay at home.","options":["rains","will rain","rained","would rain"],"answer":0,"explanation":"Mệnh đề if của câu điều kiện loại 1 dùng hiện tại đơn nên chọn rains. will rain không dùng sau if, rained và would rain thuộc loại 2."},{"prompt":"If you study hard, you ___ the exam.","options":["pass","will pass","passed","would pass"],"answer":1,"explanation":"Mệnh đề chính của loại 1 dùng will + động từ nguyên mẫu nên chọn will pass. pass thiếu will, passed và would pass sai thì."},{"prompt":"If she ___ time, she will join us.","options":["has","will have","had","would have"],"answer":0,"explanation":"Mệnh đề if dùng hiện tại đơn nên chọn has. will have không đứng sau if, had và would have thuộc câu điều kiện loại 2."}],"is_new":false},{"slug":"lien-tu-cau-ghep-cau-phuc","stage":3,"position":8,"title":"Liên từ, câu ghép và câu phức","title_en":"Conjunctions, compound and complex sentences","summary":"Phân biệt liên từ kết hợp, liên từ phụ thuộc và trạng từ liên kết; từ đó nhận diện và tạo câu ghép, câu phức chính xác.","content":"### Liên từ kết hợp (FANBOYS)\n\nBảy liên từ nối hai mệnh đề độc lập: **for, and, nor, but, or, yet, so**.\n\n- I was tired, but I finished my report. (Tôi mệt nhưng vẫn hoàn thành báo cáo.)\n- She studied hard, so she passed the exam. (Cô ấy học chăm nên đã đỗ.)\n- Trước liên từ kết hợp thường có dấu phẩy khi nối hai mệnh đề dài.\n\n### Liên từ phụ thuộc\n\nMở đầu mệnh đề phụ, không thể đứng một mình tạo thành câu hoàn chỉnh: **because, although, since, if, when, while, unless, so that**.\n\n- Although it was raining, we went out. (Dù trời mưa, chúng tôi vẫn ra ngoài.)\n- I stayed home because I felt sick. (Tôi ở nhà vì tôi thấy mệt.)\n- Mệnh đề phụ có thể đứng trước hoặc sau mệnh đề chính; đứng trước thì dùng dấu phẩy.\n\n### Trạng từ liên kết\n\nNối ý giữa hai câu, thường đứng sau dấu chấm phẩy hoặc dấu chấm: **however, therefore, moreover, for example, in addition**.\n\n- The road was flooded; therefore, we took another route. (Đường bị ngập, vì vậy chúng tôi đi đường khác.)\n- However, the plan still has some risks. (Tuy nhiên, kế hoạch vẫn còn một số rủi ro.)\n- Khác với liên từ, trạng từ liên kết không nối trực tiếp hai mệnh đề chỉ bằng một dấu phẩy.\n\n### Câu ghép và câu phức\n\n- **Câu ghép**: hai mệnh đề độc lập nối bằng liên từ kết hợp hoặc dấu chấm phẩy.\n- **Câu phức**: một mệnh đề chính và ít nhất một mệnh đề phụ thuộc.\n- **Câu ghép - phức**: kết hợp cả hai khi ý phức tạp hơn.\n\n### Lỗi thường gặp\n\n- Dùng dấu phẩy nối hai mệnh đề độc lập mà không có liên từ (comma splice).\n- Nhầm although với but trong cùng một câu: *Although it rained, but we went out* sai.\n- Dùng however như liên từ nối trực tiếp hai mệnh đề, hoặc đặt sai vị trí trạng từ liên kết.","examples":[{"en":"I wanted to go out, but it was too cold.","vi":"Tôi muốn ra ngoài, nhưng trời quá lạnh."},{"en":"Although she was tired, she kept working.","vi":"Dù cô ấy mệt, cô ấy vẫn tiếp tục làm việc."},{"en":"The road was closed; therefore, we took another route.","vi":"Con đường bị đóng, vì vậy chúng tôi đi đường khác."}],"exercises":[{"prompt":"She was tired, ___ she finished her homework.","options":["so","because","although","unless"],"answer":0,"explanation":"Hai mệnh đề có quan hệ kết quả nên dùng so. because và although chỉ nguyên nhân hoặc nhượng bộ, unless nghĩa là trừ khi, không hợp ngữ cảnh."},{"prompt":"___ it was raining, we went for a walk.","options":["Although","Because","So","Therefore"],"answer":0,"explanation":"Hai ý tương phản nên dùng Although. Because chỉ nguyên nhân, So và Therefore chỉ kết quả nên không phù hợp."},{"prompt":"He passed the exam; ___, he was very happy.","options":["however","therefore","although","because"],"answer":1,"explanation":"Đỗ kỳ thi dẫn tới việc vui nên dùng trạng từ liên kết therefore. however chỉ tương phản, although và because là liên từ phụ thuộc, không đứng sau dấu chấm phẩy như vậy."}],"is_new":true},{"slug":"cau-bi-dong-nhieu-thi","stage":4,"position":1,"title":"Câu bị động ở nhiều thì","title_en":"Passive voice across tenses","summary":"Nắm cấu trúc be + V3 và cách chia be theo từng thì để chuyển câu chủ động sang bị động chính xác.","content":"### Công thức chung\n\nCâu bị động được dùng khi ta muốn nhấn mạnh người hoặc vật chịu tác động của hành động, thay vì người thực hiện. Cấu trúc nền tảng là **be + V3/V-ed (+ by + tác nhân)**. Động từ chính luôn ở dạng quá khứ phân từ, còn thì của câu được thể hiện ở động từ be.\n\n### Chia be theo thì\n\n- Hiện tại đơn: **am/is/are + V3** — The room is cleaned every morning (Phòng được dọn mỗi sáng).\n- Quá khứ đơn: **was/were + V3** — The letter was sent yesterday (Lá thư được gửi hôm qua).\n- Hiện tại hoàn thành: **have/has been + V3** — The work has been finished (Công việc đã được hoàn thành).\n- Hiện tại tiếp diễn: **is/are being + V3** — The road is being repaired (Con đường đang được sửa).\n- Tương lai và động từ khiếm khuyết: **will be / must be + V3** — The form must be signed (Mẫu đơn phải được ký).\n\n### Cách dùng\n\n- Khi người thực hiện không rõ, không quan trọng hoặc quá hiển nhiên: My bike was stolen last night (Xe đạp của tôi bị mất trộm tối qua).\n- Khi muốn đưa đối tượng chịu tác động lên vị trí nhấn mạnh, thường gặp trong tin tức và văn bản học thuật.\n- Bỏ cụm **by + tác nhân** nếu tác nhân chung chung như people, they, someone.\n\n### Lỗi thường gặp\n\n- Giữ nguyên thì ở động từ chính thay vì chia thì ở be: sai “The house built in 1990”, đúng “The house was built in 1990”.\n- Dùng bị động với nội động từ không có tân ngữ như happen, arrive, sleep.\n- Nhầm **is being + V3** với “is been + V3”; dạng đúng của tiếp diễn bị động là is being repaired.","examples":[{"en":"The bridge was built in 1990 and is still used every day.","vi":"Cây cầu được xây năm 1990 và vẫn được sử dụng hằng ngày."},{"en":"All the documents have been checked by the manager.","vi":"Tất cả tài liệu đã được quản lý kiểm tra."},{"en":"The new policy will be announced tomorrow morning.","vi":"Chính sách mới sẽ được công bố vào sáng mai."}],"exercises":[{"prompt":"This temple ___ more than a century ago.","options":["built","was built","is built","has built"],"answer":1,"explanation":"Có mốc thời gian quá khứ “a century ago” nên dùng bị động quá khứ was built. “Built” là chủ động thiếu tân ngữ, còn “is built” sai thì."},{"prompt":"The reports ___ by the accountant at the moment.","options":["are checking","are being checked","have checked","check"],"answer":1,"explanation":"“At the moment” chỉ hành động đang diễn ra, bị động tiếp diễn là are being + V3. Các phương án còn lại đều là chủ động hoặc sai thì."},{"prompt":"Nothing ___ about the problem since last week.","options":["has done","has been done","was doing","is done"],"answer":1,"explanation":"“Since last week” đi với hiện tại hoàn thành, và “nothing” là đối tượng chịu tác động nên cần has been done. “Has done” là chủ động sai nghĩa."}],"is_new":false},{"slug":"menh-de-quan-he","stage":4,"position":2,"title":"Mệnh đề quan hệ","title_en":"Relative clauses","summary":"Dùng who, which, that, whose, where để nối hai câu và bổ sung thông tin cho danh từ, phân biệt mệnh đề xác định và không xác định.","content":"### Các đại từ quan hệ\n\n- **who**: thay cho người, làm chủ ngữ hoặc tân ngữ.\n- **whom**: thay cho người làm tân ngữ, trang trọng hơn who.\n- **which**: thay cho vật hoặc cho cả một mệnh đề phía trước.\n- **that**: thay cho người hoặc vật, chỉ dùng trong mệnh đề xác định.\n- **whose**: chỉ sở hữu, theo sau là danh từ không có mạo từ.\n- **where / when**: thay cho cụm trạng ngữ chỉ nơi chốn hoặc thời gian.\n\n### Mệnh đề xác định và không xác định\n\nMệnh đề xác định cung cấp thông tin cần thiết để nhận diện đối tượng và không có dấu phẩy: The man who called you is my uncle (Người đàn ông gọi cho bạn là chú tôi). Mệnh đề không xác định chỉ bổ sung thông tin, được tách bằng dấu phẩy và không dùng that: My uncle, who lives in Hue, is a teacher (Chú tôi, người sống ở Huế, là giáo viên).\n\n### Lược bỏ đại từ quan hệ\n\nCó thể bỏ đại từ khi nó làm tân ngữ trong mệnh đề xác định: The book I bought is interesting (Cuốn sách tôi mua rất thú vị). Không được bỏ khi đại từ làm chủ ngữ, và không bao giờ lược bỏ trong mệnh đề không xác định.\n\n### Lỗi thường gặp\n\n- Dùng that ngay sau dấu phẩy trong mệnh đề không xác định.\n- Lặp đại từ: sai “The girl who she won”, đúng “The girl who won”.\n- Dùng where cho tân ngữ chỉ vật: sai “the book where I read”, đúng “the book which I read”.","examples":[{"en":"The woman who lives next door is a doctor.","vi":"Người phụ nữ sống cạnh nhà là bác sĩ."},{"en":"This is the café where we first met.","vi":"Đây là quán cà phê nơi chúng tôi gặp nhau lần đầu."},{"en":"My brother, who works in Hanoi, is visiting us this weekend.","vi":"Anh trai tôi, người làm việc ở Hà Nội, sẽ đến thăm chúng tôi cuối tuần này."}],"exercises":[{"prompt":"The man ___ car was stolen reported it to the police.","options":["whose","who","which","whom"],"answer":0,"explanation":"Sau chỗ trống là danh từ “car” nên cần đại từ sở hữu whose. “Who” và “whom” chỉ thay cho người làm chủ ngữ hoặc tân ngữ, không đứng trước danh từ."},{"prompt":"The café ___ we met last year has closed down.","options":["which","where","who","whose"],"answer":1,"explanation":"“We met” đã đủ chủ ngữ và tân ngữ, chỗ trống thay cho cụm chỉ nơi chốn nên dùng where. “Which” sẽ tạo câu thiếu giới từ chỉ nơi chốn."},{"prompt":"Her latest novel, ___ was published in May, became a bestseller.","options":["that","which","who","what"],"answer":1,"explanation":"Đây là mệnh đề không xác định sau dấu phẩy nên dùng which, không dùng that. “Who” chỉ dùng cho người, còn “what” không làm đại từ quan hệ."}],"is_new":false},{"slug":"rut-gon-menh-de-phan-tu","stage":4,"position":3,"title":"Rút gọn mệnh đề và phân từ (V-ing / V-ed)","title_en":"Reduced relative clauses and participles","summary":"Biết khi nào bỏ đại từ quan hệ và dùng V-ing cho nghĩa chủ động, V3 cho nghĩa bị động, tránh lỗi phân từ treo.","content":"### Nguyên tắc rút gọn\n\nMệnh đề quan hệ chỉ được rút gọn khi đại từ quan hệ làm chủ ngữ. Ta bỏ đại từ, sau đó đổi động từ theo thể chủ động hoặc bị động. Cách này giúp câu ngắn gọn và tự nhiên hơn, đặc biệt trong văn viết.\n\n### Chủ động: V-ing\n\nBỏ who/which/that và đưa động từ về **V-ing**: The girl who is sitting near the window is my sister → The girl sitting near the window is my sister (Cô gái ngồi cạnh cửa sổ là chị tôi). Nếu hành động đã xảy ra trước, dùng **having + V3**: Having finished the test, he left the room (Sau khi làm xong bài, cậu ấy rời phòng).\n\n### Bị động: V3\n\nBỏ đại từ và động từ be, giữ lại **V3/V-ed**: The car which was stolen has been found → The car stolen has been found (Chiếc xe bị trộm đã được tìm thấy). Với hành động hoàn tất trước, dùng **having been + V3**.\n\n### Cụm phân từ và lỗi thường gặp\n\nCụm phân từ có thể đứng đầu câu để chỉ lý do hoặc thời gian: Walking home, I met an old friend (Trên đường về, tôi gặp một người bạn cũ). Chủ ngữ của cụm phân từ phải trùng với chủ ngữ câu chính; sai “Walking home, the rain started” vì mưa không biết đi bộ. Cũng không rút gọn khi đại từ quan hệ làm tân ngữ: sai “The book writing by Nam”, đúng “The book written by Nam”.","examples":[{"en":"The students sitting at the back couldn't hear the teacher.","vi":"Những học sinh ngồi ở phía sau không nghe được giáo viên."},{"en":"The money stolen from the office has not been found.","vi":"Số tiền bị mất trộm ở văn phòng vẫn chưa được tìm thấy."},{"en":"Having finished her homework, Lan went out with friends.","vi":"Sau khi làm xong bài tập, Lan đi chơi với bạn."}],"exercises":[{"prompt":"The documents ___ on the desk belong to the sales team.","options":["leaving","left","are left","which leaving"],"answer":1,"explanation":"Tài liệu “bị để lại” nên cần quá khứ phân từ left mang nghĩa bị động. “Leaving” mang nghĩa chủ động, còn “which leaving” sai cấu trúc."},{"prompt":"___ the report, she emailed it to the manager.","options":["Completing","Completed","Having completed","To complete"],"answer":2,"explanation":"Hành động hoàn thành báo cáo xảy ra trước khi gửi nên dùng having completed. “Completing” chỉ hành động đồng thời, “Completed” mang nghĩa bị động."},{"prompt":"The baby ___ in the next room started crying.","options":["sleeping","slept","is sleeping","sleep"],"answer":0,"explanation":"Em bé đang ngủ là chủ động nên rút gọn bằng V-ing: the baby sleeping. Các phương án còn lại sai dạng phân từ hoặc biến câu thành hai động từ chính."}],"is_new":true},{"slug":"cau-dieu-kien-loai-2","stage":4,"position":4,"title":"Câu điều kiện loại 2","title_en":"Second conditional","summary":"Diễn tả giả định trái với hiện tại bằng If + quá khứ đơn, would + V, kèm cách dùng were và unless.","content":"### Công thức\n\n**If + S + V2/V-ed, S + would/could/might + V**. Mệnh đề if dùng quá khứ đơn, mệnh đề chính dùng would + động từ nguyên mẫu. Câu điều kiện loại 2 diễn tả tình huống không có thật hoặc khó xảy ra ở hiện tại và tương lai.\n\n### Cách dùng\n\n- Đưa ra giả định trái với thực tế hiện tại: If I had a car, I would drive to work (Nếu tôi có ô tô, tôi sẽ lái xe đi làm — thực tế tôi không có).\n- Lời khuyên nhẹ nhàng với **If I were you**: If I were you, I would accept the offer (Nếu tôi là bạn, tôi sẽ nhận lời đề nghị).\n- Dùng **unless** thay cho if not: Unless you hurry, you will miss the train (Trừ khi bạn nhanh lên, bạn sẽ lỡ tàu).\n\n### Động từ be\n\nVới be, dùng **were** cho tất cả các ngôi trong văn viết chuẩn: If she were here, she would help us (Nếu cô ấy ở đây, cô ấy sẽ giúp chúng ta). Dạng was vẫn gặp trong khẩu ngữ nhưng ít trang trọng hơn.\n\n### Lỗi thường gặp\n\n- Dùng would trong mệnh đề if: sai “If I would have time”, đúng “If I had time”.\n- Dùng thì hiện tại cho giả định không thật: sai “If I am rich”, đúng “If I were rich”.\n- Nhầm với loại 1: loại 1 nói khả năng có thật (If it rains, I will stay home), loại 2 nói điều trái thực tế.","examples":[{"en":"If I had more time, I would learn to play the guitar.","vi":"Nếu tôi có nhiều thời gian hơn, tôi sẽ học chơi ghi-ta."},{"en":"If she were taller, she could join the basketball team.","vi":"Nếu cô ấy cao hơn, cô ấy có thể vào đội bóng rổ."},{"en":"What would you do if you lost your passport?","vi":"Bạn sẽ làm gì nếu bạn mất hộ chiếu?"}],"exercises":[{"prompt":"If I ___ you, I would apologize to her.","options":["am","was","were","would be"],"answer":2,"explanation":"Cấu trúc lời khuyên If I were you dùng were cho mọi ngôi. “Would be” không được xuất hiện trong mệnh đề if."},{"prompt":"We would go camping this weekend if the weather ___ better.","options":["is","was","will be","would be"],"answer":1,"explanation":"Mệnh đề chính dùng would nên đây là điều kiện loại 2, mệnh đề if cần quá khứ đơn was. “Is” và “will be” thuộc loại 1, “would be” sai vị trí."},{"prompt":"If he ___ so lazy, he would finish his work on time.","options":["isn't","weren't","won't be","wouldn't be"],"answer":1,"explanation":"Giả định trái hiện tại với be ở dạng phủ định là weren't. “Isn't” là hiện tại thật, còn “wouldn't be” không dùng trong mệnh đề if."}],"is_new":false},{"slug":"cau-dieu-kien-loai-3","stage":4,"position":5,"title":"Câu điều kiện loại 3","title_en":"Third conditional","summary":"Nói về giả định trái với quá khứ với If + had + V3, would have + V3, kể cả dạng đảo ngữ và could/might have.","content":"### Công thức\n\n**If + S + had + V3, S + would have + V3**. Mệnh đề if dùng quá khứ hoàn thành, mệnh đề chính dùng would have + quá khứ phân từ. Câu điều kiện loại 3 diễn tả giả định trái với quá khứ, điều đã không xảy ra và nay không thể thay đổi.\n\n### Cách dùng\n\n- Bày tỏ sự tiếc nuối hoặc phê phán hành động trong quá khứ: If you had told me, I would have helped you (Nếu bạn nói với tôi, tôi đã giúp bạn).\n- Suy luận ngược về nguyên nhân: If they had left earlier, they wouldn't have missed the flight (Nếu họ đi sớm hơn, họ đã không lỡ chuyến bay).\n- Thay would bằng **could have / might have** để nói khả năng hoặc kết quả có thể khác: If I had studied harder, I could have passed (Nếu tôi học chăm hơn, tôi đã có thể đỗ).\n\n### Đảo ngữ\n\nCó thể bỏ if bằng cách đảo had lên đầu câu, dùng trong văn trang trọng: Had I known the truth, I would have acted differently (Nếu tôi biết sự thật, tôi đã hành động khác).\n\n### Lỗi thường gặp\n\n- Dùng would have trong mệnh đề if: sai “If I would have known”, đúng “If I had known”.\n- Dùng quá khứ đơn thay vì quá khứ hoàn thành: sai “If I saw him yesterday”, đúng “If I had seen him yesterday” khi nói giả định trái quá khứ.\n- Nhầm với loại 2: loại 2 nói hiện tại (If I knew), loại 3 nói quá khứ (If I had known).","examples":[{"en":"If I had known about the traffic, I would have left earlier.","vi":"Nếu tôi biết về tình trạng tắc đường, tôi đã rời đi sớm hơn."},{"en":"If they had booked the tickets, they could have saved a lot of money.","vi":"Nếu họ đã đặt vé, họ đã có thể tiết kiệm được nhiều tiền."},{"en":"She wouldn't have missed the flight if she had set an alarm.","vi":"Cô ấy đã không lỡ chuyến bay nếu cô ấy đã đặt báo thức."}],"exercises":[{"prompt":"If we ___ the map, we wouldn't have got lost.","options":["didn't bring","hadn't brought","haven't brought","wouldn't bring"],"answer":1,"explanation":"Mệnh đề chính dùng wouldn't have + V3 nên mệnh đề if phải dùng quá khứ hoàn thành hadn't brought. “Didn't bring” sai thì, “wouldn't bring” không dùng trong mệnh đề if."},{"prompt":"He would have passed the exam if he ___ harder.","options":["studied","had studied","studies","would study"],"answer":1,"explanation":"Giả định trái quá khứ cần had studied ở mệnh đề if. “Studied” là loại 2, còn “would study” không đứng sau if."},{"prompt":"If you had told me earlier, I ___ you.","options":["helped","would help","would have helped","had helped"],"answer":2,"explanation":"Mệnh đề if ở quá khứ hoàn thành nên mệnh đề chính dùng would have helped. “Would help” là kết quả hiện tại của loại 2, không khớp mốc quá khứ."}],"is_new":false},{"slug":"cau-dieu-kien-hon-hop","stage":4,"position":6,"title":"Câu điều kiện hỗn hợp","title_en":"Mixed conditionals","summary":"Kết hợp hai mốc thời gian: nguyên nhân quá khứ với kết quả hiện tại, hoặc nguyên nhân hiện tại với kết quả quá khứ.","content":"### Hai dạng chính\n\nCâu điều kiện hỗn hợp kết hợp hai mốc thời gian khác nhau, thường gặp hai dạng:\n\n- Nguyên nhân ở quá khứ, kết quả ở hiện tại: **If + S + had + V3, S + would + V**.\n- Nguyên nhân ở hiện tại, kết quả ở quá khứ: **If + S + V2/V-ed, S + would have + V3**.\n\n### Dạng 1: quá khứ đến hiện tại\n\nDùng khi một việc đã xảy ra trong quá khứ để lại hậu quả đến bây giờ: If I had taken that job, I would be living in Da Nang now (Nếu tôi nhận công việc đó, giờ tôi đã sống ở Đà Nẵng). Trạng từ now, today, at the moment là dấu hiệu rõ ràng của dạng này.\n\n### Dạng 2: hiện tại đến quá khứ\n\nDùng khi tính cách hoặc tình trạng hiện tại giải thích một kết quả trong quá khứ: If she weren't so shy, she would have spoken up at the meeting (Nếu cô ấy không quá nhút nhát, cô ấy đã phát biểu ở cuộc họp). Mệnh đề if mô tả hiện tại, mệnh đề chính nói về việc đã qua.\n\n### Lỗi thường gặp\n\n- Dùng loại 3 thuần túy khi kết quả rõ ràng ở hiện tại: sai “I would have been rich now”, đúng “I would be rich now”.\n- Đổi thì cả hai vế theo cùng một mốc: sai “If I had taken that job, I would have lived in Da Nang now”.\n- Bỏ qua dấu hiệu thời gian; hãy xác định kết quả xảy ra khi nào trước khi chọn dạng.","examples":[{"en":"If I had taken that job, I would be living in Da Nang now.","vi":"Nếu tôi đã nhận công việc đó, giờ tôi đã sống ở Đà Nẵng."},{"en":"If she weren't so shy, she would have spoken up at the meeting.","vi":"Nếu cô ấy không quá nhút nhát, cô ấy đã phát biểu ở cuộc họp."},{"en":"If he had saved money, he wouldn't be in debt now.","vi":"Nếu anh ấy đã tiết kiệm tiền, giờ anh ấy đã không nợ nần."}],"exercises":[{"prompt":"If I had invested in that company, I ___ rich now.","options":["will be","would be","would have been","am"],"answer":1,"explanation":"Nguyên nhân ở quá khứ nhưng kết quả ở hiện tại (now) nên dùng would be. “Would have been” chỉ đúng khi kết quả cũng ở quá khứ."},{"prompt":"If you weren't afraid of heights, you ___ the trip last week.","options":["would enjoy","would have enjoyed","enjoyed","will enjoy"],"answer":1,"explanation":"Mệnh đề if mô tả hiện tại, còn kết quả “last week” ở quá khứ nên dùng would have enjoyed. “Would enjoy” là kết quả hiện tại, không khớp mốc thời gian."},{"prompt":"If she ___ the news yesterday, she would be here with us now.","options":["heard","had heard","hears","would hear"],"answer":1,"explanation":"Hành động nghe tin xảy ra trước mốc hiện tại nên mệnh đề if dùng had heard. “Heard” sai thì so với yesterday trong câu điều kiện hỗn hợp này."}],"is_new":false},{"slug":"wish-if-only","stage":4,"position":7,"title":"Wish / If only","title_en":"Wish / If only","summary":"Ba cấu trúc wish cho ước hiện tại, hối tiếc quá khứ và mong ai thay đổi, cùng cách dùng If only mạnh hơn.","content":"### Công thức\n\n- **S + wish + S + V2/V-ed**: ước một điều không đúng ở hiện tại.\n- **S + wish + S + had + V3**: hối tiếc một việc đã làm hoặc chưa làm trong quá khứ.\n- **S + wish + S + would + V**: mong ai đó thay đổi hoặc phàn nàn về hành vi lặp lại.\n- **If only** mang nghĩa mạnh hơn wish nhưng dùng cấu trúc giống hệt.\n\n### Cách dùng\n\n- Ước hiện tại: I wish I knew how to swim (Tôi ước mình biết bơi — thực tế không biết).\n- Hối tiếc quá khứ: I wish I hadn't said that (Tôi ước mình đã không nói điều đó).\n- Phàn nàn, mong thay đổi: I wish you would stop interrupting me (Tôi ước bạn đừng ngắt lời tôi nữa).\n- Với be, dùng **were** cho mọi ngôi: I wish she were here (Tôi ước cô ấy ở đây).\n\n### Phân biệt wish và hope\n\nHope dùng cho điều có thể thành hiện thực và theo sau là thì hiện tại hoặc will: I hope she comes tomorrow. Wish dùng cho điều trái thực tế hoặc không thể thay đổi, nên động từ luôn lùi một thì so với thời điểm được nói tới.\n\n### Lỗi thường gặp\n\n- Dùng will sau wish: sai “I wish she will come”, đúng “I wish she would come”.\n- Dùng thì hiện tại cho ước hiện tại: sai “I wish I have more time”, đúng “I wish I had more time”.\n- Nhầm wish + would với lời mời lịch sự: cấu trúc này thường thể hiện sự khó chịu, không dùng để đề nghị.","examples":[{"en":"I wish I spoke Japanese fluently.","vi":"Tôi ước mình nói tiếng Nhật lưu loát."},{"en":"If only we had booked a table in advance.","vi":"Giá mà chúng tôi đã đặt bàn trước."},{"en":"I wish you would turn down the music.","vi":"Tôi ước bạn vặn nhỏ nhạc xuống."}],"exercises":[{"prompt":"I wish I ___ how to swim.","options":["know","knew","have known","will know"],"answer":1,"explanation":"Ước một điều trái với hiện tại nên động từ lùi về quá khứ đơn knew. “Know” và “will know” không dùng sau wish, “have known” chỉ dùng cho hối tiếc quá khứ."},{"prompt":"If only I ___ my phone at the hotel.","options":["didn't leave","hadn't left","haven't left","wouldn't leave"],"answer":1,"explanation":"Đây là hối tiếc về việc đã xảy ra nên dùng hadn't left. “Didn't leave” chỉ là ước hiện tại, không diễn tả được điều đã lỡ."},{"prompt":"I wish he ___ complaining about the food.","options":["stops","stopped","would stop","had stopped"],"answer":2,"explanation":"Wish + would dùng để phàn nàn về hành vi lặp lại và mong người khác thay đổi. “Stopped” chỉ là ước hiện tại, không thể hiện rõ sự khó chịu."}],"is_new":true},{"slug":"cau-gian-tiep","stage":4,"position":8,"title":"Câu gián tiếp","title_en":"Reported speech","summary":"Quy tắc lùi thì, đổi đại từ và trạng ngữ, cùng cách tường thuật câu hỏi, mệnh lệnh chính xác.","content":"### Quy tắc lùi thì\n\nKhi động từ tường thuật ở quá khứ (said, told, asked), động từ trong lời nói gián tiếp thường lùi một thì:\n\n- Hiện tại đơn thành quá khứ đơn; hiện tại tiếp diễn thành quá khứ tiếp diễn.\n- Hiện tại hoàn thành thành quá khứ hoàn thành; quá khứ đơn thành quá khứ hoàn thành.\n- will thành would; can thành could; must thành had to.\n\n### Đổi đại từ và trạng ngữ\n\nI thành he/she, we thành they, my thành his/her; today thành that day, tomorrow thành the following day, yesterday thành the day before, here thành there, this thành that. Ví dụ: She said she would call me the next day (Cô ấy nói cô ấy sẽ gọi cho tôi ngày hôm sau).\n\n### Câu hỏi và mệnh lệnh\n\n- Câu hỏi yes/no: **asked + if/whether + S + V**, trật tự từ trở về dạng khẳng định: He asked me whether I had finished the assignment (Anh ấy hỏi tôi đã làm xong bài tập chưa).\n- Câu hỏi có từ để hỏi: giữ từ để hỏi nhưng không đảo trợ động từ: She asked where I lived.\n- Mệnh lệnh: **told/asked + O + (not) to V**: The doctor told him to take the medicine twice a day (Bác sĩ bảo anh ấy uống thuốc hai lần mỗi ngày).\n\n### Lỗi thường gặp\n\n- Giữ trật tự đảo trong câu hỏi gián tiếp: sai “He asked where was I”, đúng “He asked where I was”.\n- Nhầm say và tell: tell cần tân ngữ chỉ người, say không cần.\n- Không lùi thì dù động từ tường thuật ở quá khứ.","examples":[{"en":"She said she was moving to Hanoi the following month.","vi":"Cô ấy nói cô ấy sẽ chuyển đến Hà Nội vào tháng sau."},{"en":"He asked me whether I had finished the assignment.","vi":"Anh ấy hỏi tôi đã hoàn thành bài tập chưa."},{"en":"The doctor told him to take the medicine twice a day.","vi":"Bác sĩ bảo anh ấy uống thuốc hai lần mỗi ngày."}],"exercises":[{"prompt":"She said she ___ the report the day before.","options":["finishes","finished","has finished","had finished"],"answer":3,"explanation":"“The day before” cho thấy hành động đã hoàn thành trước lúc nói, nên lùi về quá khứ hoàn thành had finished. “Finished” không thể hiện được quan hệ trước sau."},{"prompt":"He asked me ___ interested in the position.","options":["if I was","if was I","that I was","was I"],"answer":0,"explanation":"Câu hỏi yes/no gián tiếp dùng if + trật tự khẳng định: if I was. “If was I” còn đảo trợ động từ, “that I was” sai vì đây là câu hỏi."},{"prompt":"The teacher told us ___ noise during the test.","options":["don't make","not to make","to not making","not make"],"answer":1,"explanation":"Mệnh lệnh phủ định gián tiếp là tell someone not to do something. “Don't make” giữ nguyên lời nói trực tiếp, “to not making” sai dạng động từ."}],"is_new":false},{"slug":"the-sai-khien","stage":4,"position":9,"title":"Thể sai khiến (have/get something done, make/let/have someone do)","title_en":"Causatives","summary":"Phân biệt have/get something done với make/let/have someone do và các lỗi thường gặp về dạng động từ.","content":"### Cấu trúc chính\n\n- **have/get + something + V3**: nhờ người khác làm việc gì cho mình. I had my car repaired yesterday (Hôm qua tôi đi sửa xe).\n- **get + someone + to V**: thuyết phục ai làm gì. She got her brother to carry the boxes (Cô ấy nhờ anh trai bê các thùng hàng).\n- **make/let/have + someone + V**: bắt buộc, cho phép, yêu cầu; động từ không có to. The teacher made us rewrite the essay (Giáo viên bắt chúng tôi viết lại bài).\n\n### Phân biệt make, let, have\n\nMake mang nghĩa ép buộc, let là cho phép, have là yêu cầu một cách trung tính. Ở thể bị động, make cần to: We were made to wait outside. Let chuyển thành be allowed to.\n\n### Cách dùng khác\n\n- **need + V-ing** mang nghĩa bị động: My hair needs cutting (Tóc tôi cần được cắt), tương đương needs to be cut.\n- **help + someone + (to) V**: cả hai dạng đều đúng, có to trang trọng hơn.\n- Dùng have/get something done khi muốn nhấn mạnh dịch vụ được thực hiện chứ không phải người thực hiện.\n\n### Lỗi thường gặp\n\n- Thêm to sau make/let/have: sai “made us to wait”, đúng “made us wait”.\n- Dùng V-ing sau have: sai “have my car repairing”, đúng “have my car repaired”.\n- Nhầm get someone do với get someone to do: dạng đúng luôn có to trước động từ.","examples":[{"en":"I had my car repaired yesterday.","vi":"Hôm qua tôi đã cho người sửa xe của mình."},{"en":"She got her brother to carry the boxes upstairs.","vi":"Cô ấy nhờ anh trai bê các thùng hàng lên lầu."},{"en":"The teacher made us rewrite the essay.","vi":"Giáo viên bắt chúng tôi viết lại bài luận."}],"exercises":[{"prompt":"I need to get my hair ___ before the wedding.","options":["cut","to cut","cutting","be cut"],"answer":0,"explanation":"Get something done dùng quá khứ phân từ cut vì tóc được người khác cắt. “To cut” và “cutting” sai dạng, “be cut” không đứng sau get trong cấu trúc này."},{"prompt":"The manager made the team ___ the proposal again.","options":["to revise","revising","revise","revised"],"answer":2,"explanation":"Sau make + tân ngữ là động từ nguyên mẫu không to, nên dùng revise. “To revise” sai vì make không đi với to, “revised” mang nghĩa bị động."},{"prompt":"She had the documents ___ by a professional translator.","options":["translate","translating","translated","to translate"],"answer":2,"explanation":"Have something done cần quá khứ phân từ translated vì tài liệu được dịch bởi người khác. Các phương án còn lại sai dạng phân từ hoặc thêm to không đúng."}],"is_new":true},{"slug":"cau-tao-tu","stage":5,"position":1,"title":"Cấu tạo từ (word formation: hậu tố, tiền tố)","title_en":"Word formation","summary":"Nhận diện tiền tố đổi nghĩa và hậu tố quyết định từ loại để chọn đúng dạng từ trong câu, đặc biệt ở câu hỏi từ loại của đề thi.","content":"### Tiền tố thay đổi nghĩa\n\nTiền tố (prefix) đứng trước từ gốc và đổi nghĩa chứ không đổi từ loại. Nhóm phủ định quen thuộc gồm **un-**, **in-**, **im-**, **il-**, **ir-**, **dis-**, **non-**, **mis-** (unfair: không công bằng; impossible: không thể; misunderstand: hiểu nhầm). Nhóm chỉ mức độ hoặc thời gian gồm **re-** (làm lại), **pre-** (trước), **post-** (sau), **over-** (quá mức), **under-** (dưới mức), **sub-** (dưới), **inter-** (giữa các). Khi gặp từ lạ, hãy tách tiền tố rồi đoán nghĩa từ phần còn lại.\n\n### Hậu tố quyết định từ loại\n\nHậu tố (suffix) đứng sau từ gốc và quyết định từ loại, đây là điểm được hỏi nhiều nhất trong đề thi.\n\n- Danh từ: **-tion/-sion**, **-ment**, **-ness**, **-ity**, **-ance/-ence**, **-er/-or**, **-ist**, **-ship** (decision, development, happiness, ability, performance, employer, scientist, leadership).\n- Tính từ: **-ful**, **-less**, **-ous**, **-ive**, **-able/-ible**, **-al**, **-ic** (careful, careless, dangerous, effective, reliable, national, economic).\n- Động từ: **-ize/-ise**, **-ify**, **-en**, **-ate** (modernize, simplify, strengthen, activate).\n- Trạng từ: **-ly** (carefully, rapidly).\n\n### Cách dùng khi làm bài\n\n- Xác định vị trí cần điền: sau mạo từ hoặc tính từ sở hữu thường là danh từ; sau động từ liên kết **be, seem, become** thường là tính từ; bổ nghĩa cho động từ thường là trạng từ.\n- Nếu bốn lựa chọn cùng gốc, chỉ khác hậu tố thì câu hỏi đang kiểm tra từ loại chứ không phải nghĩa.\n- Đọc cả câu để phát hiện phủ định; tiền tố phủ định có thể làm đổi nghĩa hoàn toàn (The report was incomplete - báo cáo chưa đầy đủ).\n\n### Lỗi thường gặp\n\n- Chọn trạng từ khi vị trí cần tính từ bổ nghĩa cho danh từ.\n- Nhầm **-ing** và **-ed** của tính từ: dùng **-ed** cho cảm xúc của người, **-ing** cho tính chất gây ra cảm xúc (bored/boring).\n- Viết sai chính tả khi thêm hậu tố, ví dụ bỏ **e** trước **-ment** hoặc đổi **y** thành **i**.","examples":[{"en":"The supervisor thanked the staff for their patience during the transition.","vi":"Người giám sát cảm ơn nhân viên vì sự kiên nhẫn của họ trong thời gian chuyển đổi."},{"en":"The instructions were unclear, so several employees made mistakes.","vi":"Hướng dẫn không rõ ràng nên nhiều nhân viên đã mắc lỗi."},{"en":"Our department will modernize the filing system next quarter.","vi":"Bộ phận chúng tôi sẽ hiện đại hóa hệ thống lưu hồ sơ vào quý sau."}],"exercises":[{"prompt":"The manager praised the team for their ___ to the project.","options":["commit","committed","commitment","committing"],"answer":2,"explanation":"Sau tính từ sở hữu their cần một danh từ, và commitment là danh từ duy nhất trong các lựa chọn. Các từ còn lại là động từ hoặc dạng V-ing/V-ed."},{"prompt":"The new policy is ___ with the company's long-term goals.","options":["consistent","consistence","consistently","consist"],"answer":0,"explanation":"Sau động từ be cần tính từ, và cụm cố định be consistent with nghĩa là phù hợp với. Consistence là danh từ, consistently là trạng từ nên không đứng sau be."},{"prompt":"Because the instructions were ___, the staff could not follow them.","options":["clear","clearly","unclear","clarity"],"answer":2,"explanation":"Vị trí sau were cần tính từ, và vế sau cho thấy nghĩa phủ định nên phải dùng unclear. Clearly là trạng từ, clarity là danh từ."}],"is_new":true},{"slug":"phrasal-verbs","stage":5,"position":2,"title":"Phrasal verbs","title_en":"Phrasal verbs","summary":"Nắm cách cấu tạo, phân loại và trật tự tân ngữ của cụm động từ, đồng thời học các cụm thường gặp trong môi trường công việc.","content":"### Cấu tạo và phân loại\n\nCụm động từ (phrasal verb) gồm một động từ và một tiểu từ như **up, down, in, out, off, on, over, away**. Nghĩa của cả cụm thường khác nghĩa động từ gốc, không thể suy luận từng từ. Có hai nhóm chính: nội động, không cần tân ngữ (break down: hỏng máy) và ngoại động, cần tân ngữ.\n\n- Không tách được: tân ngữ luôn đứng sau tiểu từ (look after the children - chăm sóc bọn trẻ).\n- Tách được: tân ngữ có thể đứng giữa hoặc sau tiểu từ (turn off the light / turn the light off).\n- Nếu tân ngữ là đại từ **it, them, him, her** thì bắt buộc đứng giữa: turn it off, không nói turn off it.\n\n### Nhóm theo động từ gốc\n\n- **take**: take off (cất cánh, cởi), take over (tiếp quản), take up (bắt đầu một sở thích), take after (giống ai).\n- **put**: put off (hoãn), put on (mặc vào), put out (dập tắt), put up with (chịu đựng).\n- **turn**: turn down (từ chối, giảm âm lượng), turn up (đến, tăng âm lượng), turn in (nộp).\n- **look**: look into (điều tra), look after (chăm sóc), look forward to (mong chờ), look up (tra cứu).\n\n### Cách dùng trong ngữ cảnh công việc\n\nTrong đề thi và email công sở, hãy dựa vào tiểu từ đi kèm và nghĩa của cả câu thay vì dịch từng chữ. Ví dụ **carry out a survey** (tiến hành khảo sát), **come up with a plan** (nghĩ ra kế hoạch), **go over the figures** (xem lại số liệu).\n\n### Lỗi thường gặp\n\n- Đặt đại từ sau tiểu từ: sai **pick up it**, đúng **pick it up**.\n- Dùng sai tiểu từ vì nghĩa gần giống nhau: **turn down** là từ chối, không phải giảm nhiệt độ.\n- Chia sai thì khi cụm động từ ở dạng quá khứ: chỉ động từ chính thêm **-ed**, tiểu từ giữ nguyên (called off, không phải call offed).","examples":[{"en":"The flight was called off because of heavy fog.","vi":"Chuyến bay bị hủy vì sương mù dày."},{"en":"She took over the department after her manager retired.","vi":"Cô ấy tiếp quản bộ phận sau khi quản lý của mình nghỉ hưu."},{"en":"Please fill out the form and hand it in at the front desk.","vi":"Vui lòng điền vào mẫu đơn và nộp ở quầy lễ tân."}],"exercises":[{"prompt":"The meeting was ___ until next Monday because of the storm.","options":["put on","put off","put up","put out"],"answer":1,"explanation":"Put off nghĩa là hoãn, phù hợp với việc dời cuộc họp sang thứ Hai. Put on là mặc vào, put up là dựng lên, put out là dập tắt."},{"prompt":"Please ___ your report by Friday at the latest.","options":["turn up","turn down","turn in","turn over"],"answer":2,"explanation":"Turn in nghĩa là nộp, đúng với việc nộp báo cáo. Turn up là xuất hiện, turn down là từ chối, turn over là chuyển giao."},{"prompt":"The manager asked the team to ___ the complaint immediately.","options":["look after","look up","look into","look forward to"],"answer":2,"explanation":"Look into nghĩa là điều tra, xem xét, phù hợp với việc xử lý một lời phàn nàn. Look after là chăm sóc, look up là tra cứu, look forward to là mong chờ."}],"is_new":true},{"slug":"so-such-too-enough","stage":5,"position":3,"title":"So / Such / Too / Enough","title_en":"So / Such / Too / Enough","summary":"Phân biệt bốn cấu trúc chỉ mức độ qua từ loại đi kèm và ý nghĩa tích cực hay tiêu cực của câu.","content":"### Công thức cơ bản\n\nBốn cấu trúc này đều nói về mức độ nhưng khác nhau ở từ loại đi kèm và trật tự câu.\n\n- **so + tính từ/trạng từ + that + mệnh đề**: The soup was so salty that nobody finished it (món súp mặn đến mức không ai ăn hết).\n- **such + (a/an) + tính từ + danh từ + that + mệnh đề**: It was such a long journey that we stopped twice (chuyến đi dài đến mức chúng tôi dừng hai lần).\n- **too + tính từ/trạng từ + to + động từ**: The box is too heavy to lift (cái hộp quá nặng để nâng).\n- **tính từ/trạng từ + enough + to + động từ**: She is old enough to drive (cô ấy đủ tuổi để lái xe).\n\n### Cách dùng\n\n- **So** và **such** nhấn mạnh mức độ dẫn tới một kết quả, thường đi với **that**. **Such** đứng trước cụm danh từ, **so** đứng trước tính từ đơn lẻ.\n- **Too** mang nghĩa tiêu cực, hàm ý không thể thực hiện được hành động phía sau. **Enough** mang nghĩa đủ, tích cực hơn.\n- **Enough** đứng sau tính từ nhưng đứng trước danh từ: enough money (đủ tiền), not rich enough (không đủ giàu).\n\n### Dấu hiệu nhận biết nhanh\n\n- Thấy **that** phía sau và trước chỗ trống là tính từ đơn lẻ thì chọn **so**.\n- Thấy cụm **a/an + tính từ + danh từ** thì chọn **such**, không dùng **so**.\n- Thấy **to + động từ** phía sau thì cân nhắc **too** hoặc **enough** tùy nghĩa câu.\n\n### Lỗi thường gặp\n\n- Viết **so a difficult test**, đúng là **such a difficult test**.\n- Dùng **too ... to** cho nghĩa tích cực, ví dụ sai **He is too tall to reach the shelf**.\n- Đặt **enough** trước tính từ: sai **enough old**, đúng **old enough**.","examples":[{"en":"The lecture was so boring that half the audience left early.","vi":"Bài giảng nhàm chán đến mức nửa khán giả ra về sớm."},{"en":"It was such a difficult test that many students ran out of time.","vi":"Bài kiểm tra khó đến mức nhiều học sinh hết thời gian."},{"en":"This box is too heavy for me to lift alone.","vi":"Cái hộp này quá nặng để tôi nâng một mình."}],"exercises":[{"prompt":"The coffee was ___ hot that I could not drink it.","options":["such","so","too","enough"],"answer":1,"explanation":"Trước tính từ hot và sau là mệnh đề that nên dùng so. Such phải đi với cụm danh từ, too và enough không đi với that theo cấu trúc này."},{"prompt":"It was ___ a complicated form that nobody could complete it.","options":["so","such","too","very"],"answer":1,"explanation":"Có cụm a complicated form là cụm danh từ nên phải dùng such. So chỉ đứng trước tính từ đơn lẻ, còn very không đi với that."},{"prompt":"The room is not warm ___ for the children to sleep in.","options":["enough","too","so","such"],"answer":0,"explanation":"Enough đứng sau tính từ warm và trước cụm to + động từ, nghĩa là đủ ấm. Too mang nghĩa quá mức nên trái với ý câu."}],"is_new":true},{"slug":"dao-ngu-va-cau-nhan-manh","stage":5,"position":4,"title":"Đảo ngữ và câu nhấn mạnh","title_en":"Inversion and emphasis","summary":"Nắm các mẫu đảo ngữ cố định và câu chẻ để nhấn mạnh thông tin, tránh sai trật tự từ khi viết trang trọng.","content":"### Đảo ngữ là gì\n\nĐảo ngữ (inversion) là hiện tượng đưa trợ động từ hoặc động từ lên trước chủ ngữ, thường dùng để nhấn mạnh hoặc theo cấu trúc cố định. Trật tự chuẩn là **trạng từ phủ định + trợ động từ + chủ ngữ + động từ chính**. Ví dụ Never have I seen such a result (tôi chưa từng thấy kết quả như vậy).\n\n### Các dạng đảo ngữ thường gặp\n\n- Với **never, rarely, seldom, hardly, little, nowhere**: Never does she arrive late (cô ấy không bao giờ đến muộn).\n- Với **not only ... but also**: Not only did he finish early, but he also helped others (anh ấy không chỉ xong sớm mà còn giúp người khác).\n- Với **only after, only when, only if** ở đầu câu: Only after the audit did the company realize the error (chỉ sau cuộc kiểm toán công ty mới nhận ra lỗi).\n- Với **no sooner ... than** và **hardly ... when**: Hardly had the meeting begun when the alarm rang (cuộc họp vừa bắt đầu thì chuông báo cháy vang lên).\n\n### Câu nhấn mạnh\n\n- Câu chẻ với **It is/was ... that**: It was the marketing team that proposed the new slogan (chính nhóm marketing đã đề xuất khẩu hiệu mới).\n- Câu chẻ với **What ... is/was**: What we need is more time (điều chúng ta cần là thêm thời gian).\n- **Do/does/did** đứng trước động từ để nhấn mạnh khẳng định: I do appreciate your help (tôi thực sự trân trọng sự giúp đỡ của bạn).\n\n### Lỗi thường gặp\n\n- Đảo ngữ nhưng quên chia trợ động từ theo thì: sai **Never she has seen**, đúng **Never has she seen**.\n- Dùng **that** thay cho **when** sau **hardly**: đúng là hardly ... when.\n- Đảo ngữ ở cả mệnh đề phụ không cần thiết, khiến câu sai trật tự so với cấu trúc cố định.","examples":[{"en":"Rarely does the company accept late applications.","vi":"Hiếm khi công ty chấp nhận đơn đăng ký muộn."},{"en":"Not only did she finish the report, but she also presented it.","vi":"Cô ấy không chỉ hoàn thành báo cáo mà còn trình bày nó."},{"en":"It was the design team that won the annual award.","vi":"Chính nhóm thiết kế là bên giành giải thưởng thường niên."}],"exercises":[{"prompt":"Never ___ I seen such a well-prepared presentation.","options":["has","have","had","do"],"answer":1,"explanation":"Chủ ngữ là I nên trợ động từ phải là have, và đảo ngữ đưa have lên trước chủ ngữ. Has chỉ dùng với ngôi thứ ba số ít."},{"prompt":"Only after the audit ___ the company realize the error.","options":["does","was","did","had"],"answer":2,"explanation":"Mệnh đề chính dùng động từ nguyên mẫu realize ở quá khứ nên cần trợ động từ did. Had sẽ tạo thành thì quá khứ hoàn thành không phù hợp với realize."},{"prompt":"It was in 2019 ___ the branch opened.","options":["which","when","that","where"],"answer":2,"explanation":"Đây là câu chẻ nhấn mạnh trạng ngữ thời gian, cấu trúc cố định là It was ... that. Which, when và where không dùng trong mẫu này."}],"is_new":true},{"slug":"on-ngu-phap-toeic-part-5-6","stage":5,"position":5,"title":"Ôn ngữ pháp TOEIC Part 5–6","title_en":"TOEIC Part 5–6 grammar","summary":"Chiến lược xử lý câu điền khuyết và đoạn điền khuyết: nhận diện dạng câu hỏi, loại trừ theo từ loại và quản lý thời gian.","content":"### Cấu trúc phần thi\n\nPart 5 gồm các câu điền khuyết ngắn, mỗi câu có một chỗ trống và bốn lựa chọn. Part 6 là đoạn văn ngắn có nhiều chỗ trống, đòi hỏi đọc cả ngữ cảnh chứ không chỉ một câu. Cả hai phần đều kiểm tra ngữ pháp và từ vựng trong tình huống công việc.\n\n### Dạng câu hỏi thường gặp\n\n- Từ loại: bốn lựa chọn cùng gốc, khác hậu tố (decide, decision, decisive, decisively).\n- Thì và hòa hợp chủ vị, đặc biệt khi chủ ngữ dài hoặc có cụm xen giữa.\n- Giới từ và cụm giới từ cố định (responsible for, comply with, in charge of).\n- Đại từ quan hệ và liên từ nối hai mệnh đề.\n- Từ vựng doanh nghiệp: hợp đồng, giao hàng, tuyển dụng, lịch họp.\n\n### Chiến lược làm bài\n\n- Đọc hết câu trước khi nhìn lựa chọn để nắm nghĩa, sau đó mới xác định vị trí trống cần từ loại gì.\n- Với Part 6, đọc lướt cả đoạn để biết chủ đề và thì chung; câu trước và câu sau thường quyết định đáp án.\n- Loại trừ theo từ loại trước rồi mới xét nghĩa; cách này nhanh hơn dịch toàn bộ câu.\n- Không dừng quá lâu ở một câu; câu khó hãy đánh dấu và quay lại sau.\n\n### Quy trình chữa lỗi\n\n- Ghi lại câu sai, đáp án đã chọn, đáp án đúng và lý do chọn sai.\n- Phân loại lỗi theo nhóm kiến thức để thấy nhóm nào lặp lại nhiều nhất.\n- Làm lại các câu đã sai sau vài ngày, chỉ gạch tên khi đã đúng hai lần liên tiếp.","examples":[{"en":"Applicants are requested to submit their documents by March 15.","vi":"Ứng viên được yêu cầu nộp hồ sơ trước ngày 15 tháng 3."},{"en":"The new software significantly reduces the time needed for data entry.","vi":"Phần mềm mới giúp giảm đáng kể thời gian nhập dữ liệu."},{"en":"Due to limited seating, early registration is highly recommended.","vi":"Do số ghế có hạn nên rất nên đăng ký sớm."}],"exercises":[{"prompt":"All employees must ___ their identification badges at all times.","options":["wear","wears","wearing","worn"],"answer":0,"explanation":"Sau động từ khuyết thiếu must phải dùng động từ nguyên mẫu wear. Wears chia theo ngôi, wearing và worn không đứng sau must."},{"prompt":"The shipment will be delivered ___ Friday afternoon.","options":["until","since","by","during"],"answer":2,"explanation":"By + mốc thời gian nghĩa là trước hoặc muộn nhất vào lúc đó. Until nhấn mạnh kéo dài đến mốc, since chỉ mốc bắt đầu, during đi với danh từ chỉ khoảng thời gian."},{"prompt":"Ms. Chen is responsible ___ training new staff.","options":["of","for","to","with"],"answer":1,"explanation":"Cụm cố định là be responsible for + danh từ/V-ing, nghĩa là chịu trách nhiệm về việc gì. Of, to và with không tạo thành cụm này."}],"is_new":false},{"slug":"luyen-de-va-so-loi-sai","stage":5,"position":6,"title":"Luyện đề và sổ lỗi sai","title_en":"Practice tests and error log","summary":"Biến mỗi đề đã làm thành dữ liệu học tập bằng cách ghi lỗi có hệ thống, phân loại nguyên nhân và ôn lại theo chu kỳ.","content":"### Quy trình làm một đề\n\nLàm đề là bước kiểm tra chứ không phải bước học kiến thức mới. Hãy làm trong điều kiện giống thi: đủ thời gian, không tra từ điển, không dừng quá lâu ở một câu. Sau khi hết giờ mới chấm điểm và ghi lại thời điểm bắt đầu, kết thúc để biết tốc độ của mình.\n\n### Cách ghi sổ lỗi sai\n\n- Mỗi lỗi ghi thành một dòng gồm câu gốc, đáp án đã chọn, đáp án đúng và lý do sai.\n- Gắn nhãn theo nhóm: từ loại, thì, giới từ, mệnh đề quan hệ, từ vựng, đọc hiểu.\n- Với lỗi do không biết từ, ghi thêm nghĩa và một câu ví dụ do bạn tự đặt.\n- Đánh dấu mức độ: lỗi do thiếu kiến thức hay do bất cẩn; hai loại này cần cách xử lý khác nhau.\n\n### Phân tích kết quả\n\nĐừng chỉ nhìn số câu đúng. Hãy đếm số lỗi theo từng nhóm để chọn nội dung ôn tiếp theo. Nếu phần lớn lỗi nằm ở một nhóm, ôn lại lý thuyết nhóm đó rồi làm thêm câu cùng dạng trước khi chuyển sang nhóm khác.\n\n### Vòng lặp ôn tập\n\n- Ngày 1: làm đề và ghi lỗi.\n- Ngày 2: học lại lý thuyết của nhóm lỗi nhiều nhất.\n- Ngày 4: làm lại đúng những câu đã sai.\n- Ngày 7: làm đề mới, so sánh tỉ lệ lỗi theo nhóm với lần trước.\n\nChỉ khi tỉ lệ lỗi của một nhóm giảm rõ rệt mới coi là đã xử lý xong nhóm đó.","examples":[{"en":"Neither the supervisor nor the technicians were informed about the change.","vi":"Cả người giám sát lẫn các kỹ thuật viên đều không được thông báo về thay đổi."},{"en":"The proposal, along with the budget estimate, has been forwarded to headquarters.","vi":"Bản đề xuất cùng với dự toán ngân sách đã được chuyển đến trụ sở chính."},{"en":"If payment is received today, the goods will be shipped tomorrow.","vi":"Nếu thanh toán được nhận hôm nay thì hàng sẽ được gửi đi vào ngày mai."}],"exercises":[{"prompt":"Neither the manager nor the employees ___ aware of the new schedule.","options":["was","were","is","has"],"answer":1,"explanation":"Với neither ... nor, động từ chia theo chủ ngữ gần nhất là employees số nhiều, nên dùng were. Was và is là dạng số ít, has không hợp nghĩa."},{"prompt":"The contract, along with the appendices, ___ been signed.","options":["have","has","having","to have"],"answer":1,"explanation":"Chủ ngữ chính là the contract số ít; cụm along with the appendices chỉ bổ sung nên không làm đổi số của động từ. Vì vậy dùng has."},{"prompt":"If the order ___ today, it will arrive by Friday.","options":["placed","will be placed","is placed","placing"],"answer":2,"explanation":"Câu điều kiện loại một dùng hiện tại đơn ở mệnh đề if, và order là đối tượng được đặt nên cần dạng bị động is placed. Will be placed không dùng trong mệnh đề if."}],"is_new":false},{"slug":"on-tap-tong-hop","stage":5,"position":7,"title":"Ôn tập tổng hợp","title_en":"Comprehensive review","summary":"Hệ thống hóa toàn bộ kiến thức đã học, tập trung vào các cặp dễ nhầm và chiến lược ôn theo nhóm lỗi.","content":"### Hệ thống lại kiến thức\n\nTrước khi ôn, hãy lập danh sách các nhóm kiến thức đã học: từ loại và cấu tạo từ, thì, câu bị động, mệnh đề quan hệ, câu điều kiện, so sánh, giới từ, liên từ. Với mỗi nhóm, viết một dòng công thức cốt lõi và một ví dụ của riêng bạn. Việc tự viết ví dụ giúp phát hiện chỗ hiểu chưa chắc.\n\n### Các cặp dễ nhầm\n\n- **Số ít hay số nhiều của chủ ngữ**: the number of + danh từ số nhiều nhưng động từ số ít; a number of + danh từ số nhiều và động từ số nhiều.\n- **Tính từ và trạng từ**: tính từ bổ nghĩa danh từ, trạng từ bổ nghĩa động từ hoặc tính từ.\n- **Mệnh đề quan hệ xác định và không xác định**: mệnh đề không xác định đứng sau dấu phẩy và không dùng **that**.\n- **Hiện tại hoàn thành và quá khứ đơn**: hiện tại hoàn thành gắn với hiện tại, quá khứ đơn gắn với mốc thời gian đã kết thúc.\n- **Bị động và chủ động**: xác định ai thực hiện hành động trước khi chọn dạng động từ.\n\n### Chiến lược ôn tập\n\n- Ôn theo nhóm lỗi, không ôn tràn lan theo thứ tự sách.\n- Xen kẽ dạng bài: một lượt lý thuyết, một lượt câu hỏi ngắn, một lượt đọc hiểu.\n- Tự giải thích đáp án thành lời; nếu không giải thích được thì chưa nắm.\n- Dành thời gian cuối để rà lại những câu từng sai, không học thêm kiến thức mới.\n\n### Lỗi thường gặp\n\n- Chọn đáp án theo cảm giác quen tai thay vì kiểm tra cấu trúc.\n- Bỏ qua cụm xen giữa khi xác định chủ ngữ.\n- Dịch cả câu quá lâu trong khi chỉ cần xác định từ loại tại chỗ trống.","examples":[{"en":"A number of employees have volunteered for the weekend shift.","vi":"Một số nhân viên đã tình nguyện làm ca cuối tuần."},{"en":"She speaks English more fluently than her colleague.","vi":"Cô ấy nói tiếng Anh trôi chảy hơn đồng nghiệp của mình."},{"en":"Hardly had she arrived when the client called.","vi":"Cô ấy vừa mới đến thì khách hàng gọi."}],"exercises":[{"prompt":"The number of applicants ___ increased sharply this year.","options":["have","has","having","to have"],"answer":1,"explanation":"Chủ ngữ là the number of applicants, trong đó the number là số ít nên động từ dùng has. Have chỉ đúng với cấu trúc a number of + danh từ số nhiều."},{"prompt":"She speaks English ___ than her colleague.","options":["more fluent","more fluently","fluent","fluency"],"answer":1,"explanation":"Trạng từ fluently bổ nghĩa cho động từ speaks và dùng dạng so sánh hơn more fluently. Fluent là tính từ, fluency là danh từ."},{"prompt":"Hardly ___ the guests sat down when the lights went out.","options":["has","did","had","was"],"answer":2,"explanation":"Cấu trúc hardly ... when dùng quá khứ hoàn thành, và đảo ngữ đưa had lên trước chủ ngữ. Did và was không tạo đúng thì quá khứ hoàn thành cho mệnh đề này."}],"is_new":false},{"slug":"de-toeic-tong-hop","stage":5,"position":8,"title":"Đề TOEIC tổng hợp","title_en":"Full TOEIC practice","summary":"Luyện đề trọn quy trình: mô phỏng điều kiện thi, phân bổ thời gian hợp lý và phân tích kết quả để hành động ở lần sau.","content":"### Mô phỏng điều kiện thi\n\nĐề tổng hợp dùng để kiểm tra sức bền và khả năng phân bổ thời gian. Hãy làm liền mạch, không nghỉ giữa các phần, không tra cứu. Chuẩn bị giấy nháp để đánh dấu câu chưa chắc và quay lại nếu còn thời gian.\n\n### Phân bổ thời gian\n\n- Chia thời gian theo từng phần thi, không để một phần chiếm quá nhiều.\n- Lượt một: làm các câu chắc chắn, bỏ qua câu cần suy nghĩ lâu.\n- Lượt hai: quay lại câu đã đánh dấu, xử lý theo thứ tự dễ đến khó.\n- Luôn để thời gian cuối để tô đáp án và kiểm tra những câu bỏ trống.\n\n### Dạng câu hỏi dễ mất điểm\n\n- Câu có mệnh đề xen giữa khiến chủ ngữ và động từ cách xa nhau.\n- Câu có hai mệnh đề nối bằng liên từ, cần xác định thì của từng mệnh đề.\n- Đoạn văn có chỗ trống là câu nối ý, phải đọc cả câu trước và câu sau.\n- Từ vựng gần nghĩa, chỉ phân biệt được bằng ngữ cảnh.\n\n### Quy trình sau khi làm đề\n\n- Chấm điểm và ghi lại tỉ lệ đúng theo từng phần.\n- Chọn ba lỗi nghiêm trọng nhất để phân tích kỹ thay vì xem lại toàn bộ.\n- Ghi vào sổ lỗi và phân loại theo nhóm kiến thức như khi luyện đề.\n- Lên kế hoạch ôn cho tuần tiếp theo dựa trên nhóm lỗi lặp lại nhiều nhất.\n\nMột đề chỉ có giá trị khi bạn rút ra được hành động cụ thể cho lần làm sau.","examples":[{"en":"The workshop will cover basic safety procedures for new staff.","vi":"Buổi tập huấn sẽ đề cập các quy trình an toàn cơ bản cho nhân viên mới."},{"en":"The invoice must be approved by the finance department before payment.","vi":"Hóa đơn phải được bộ phận tài chính phê duyệt trước khi thanh toán."},{"en":"Please confirm your attendance no later than two days before the event.","vi":"Vui lòng xác nhận việc tham dự muộn nhất là hai ngày trước sự kiện."}],"exercises":[{"prompt":"The company is looking for a candidate with strong ___ skills.","options":["lead","leader","leadership","leading"],"answer":2,"explanation":"Trước danh từ skills cần một danh từ bổ nghĩa, và leadership skills nghĩa là kỹ năng lãnh đạo. Lead là động từ hoặc danh từ chỉ kim loại, leading là tính từ không hợp cụm này."},{"prompt":"All travel expenses will be ___ by the company.","options":["reimburse","reimbursed","reimbursing","reimbursement"],"answer":1,"explanation":"Câu bị động với will be cần quá khứ phân từ reimbursed, nghĩa là được hoàn trả. Reimburse là nguyên mẫu, reimbursement là danh từ."},{"prompt":"The workshop is intended for staff ___ are new to the department.","options":["who","which","whom","whose"],"answer":0,"explanation":"Đại từ quan hệ thay cho staff chỉ người và làm chủ ngữ của are nên dùng who. Whom làm tân ngữ, which chỉ vật, whose chỉ sở hữu."}],"is_new":false}]$seed$::jsonb as data)
insert into public.grammar_topics
  (slug, stage, position, title, title_en, summary, content, examples, exercises, is_new, updated_at)
select x.slug, x.stage, x.position, x.title, x.title_en, x.summary, x.content,
       x.examples, x.exercises, x.is_new, now()
from payload, jsonb_to_recordset(payload.data) as x(
  slug text, stage smallint, position smallint, title text, title_en text, summary text,
  content text, examples jsonb, exercises jsonb, is_new boolean
)
on conflict (slug) do update set
  stage = excluded.stage,
  position = excluded.position,
  title = excluded.title,
  title_en = excluded.title_en,
  summary = excluded.summary,
  content = excluded.content,
  examples = excluded.examples,
  exercises = excluded.exercises,
  is_new = excluded.is_new,
  updated_at = now();
